import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-d1-001","clusterId":"D","werkstueckRef":"D.1.1","stufe":2,"question":"Was ist an diesem Einwand der Kern des Denkfehlers, und was wäre der bessere nächste Schritt?","scenario":"In einer Diskussion über den Klimawandel sagt jemand: „Die Studie, die du zitierst, wurde von einem Ölkonzern finanziert. Damit ist sie wertlos.“ Die Studie selbst hat er nicht gelesen.","options":["Er schließt allein aus der Finanzierung, dass die Daten falsch sind. Besser: die Geldgeber als Anlass für besonders genaues Hinsehen nehmen und Methode und Daten der Studie selbst prüfen.","Er verallgemeinert von einer einzelnen Studie auf die gesamte Klimaforschung. Besser: möglichst viele Studien zum Thema sammeln, vergleichen und das Gesamtbild beurteilen, statt eine einzelne zu bewerten.","Er wirft der Studie Aussagen vor, die sie gar nicht macht, und kritisiert so einen Strohmann. Besser: wörtlich wiedergeben, was die Studie behauptet, und erst dann darauf antworten.","Er verschiebt die Messlatte, sobald ein Beleg vorliegt, sodass nichts ihn überzeugen kann. Besser: vorab festlegen, welcher Beleg ihn überzeugen würde, und diesen dann gelten lassen."],"correctIndex":0,"explanation":"Wer bezahlt, kann ein Motiv für verzerrte Ergebnisse sein. Das ist ein guter Grund, die Studie besonders kritisch zu lesen, etwa auf Methodik, Datenlage und unabhängige Replikation zu achten. Ob die Daten falsch sind, folgt daraus aber nicht: Die Geldgeber sagen etwas über mögliche Interessen, nicht über die Richtigkeit der Messwerte. Zum Fehlschluss wird der Einwand, sobald die Frage nach der Finanzierung die Prüfung der Studie selbst ersetzt, statt sie zu ergänzen. Verallgemeinert wird hier nichts, denn der Sprecher urteilt nur über diese eine Studie. Aussagen der Studie unterstellt er ebenfalls keine, er hat sie ja gar nicht gelesen. Und eine verschobene Messlatte liegt nicht vor, denn er lehnt die Studie von vornherein wegen ihrer Quelle ab.","coreRule":"⚡ Wer bezahlt, ist ein Grund zum Genauhinsehen – ein Gegenbeweis ist es nicht.","beleg":"Werkstück D.1.1 (Formen des Ad-hominem-Angriffs: interessenbasiert; Der Kipppunkt)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Die Finanzierung ist ein guter Grund, eine Studie besonders genau zu lesen, aber kein Beweis, dass ihre Daten falsch sind. Der Fehler beginnt, wo die Frage nach dem Geldgeber die Prüfung von Methode und Daten ersetzt, statt sie zu ergänzen.","prueffrage":"Hat der Sprecher irgendetwas am Inhalt der Studie beanstandet, oder stützt sich sein ganzer Einwand auf den Geldgeber?","rueckmeldung":[{"option":1,"text":"Mehrere Studien zu vergleichen ist ein guter Weg, ein Gesamtbild zu gewinnen. Hier aber urteilt der Sprecher nur über diese eine Studie und verallgemeinert nichts. Sein Fehler liegt darin, dass er sie wegen ihrer Quelle verwirft, ohne sie geprüft zu haben."},{"option":2,"text":"Genau wiederzugeben, was jemand behauptet, schützt vor Verzerrungen. Eine Verdrehung findet hier aber nicht statt: Der Sprecher hat die Studie gar nicht gelesen und unterstellt ihr keine Aussagen. Er lehnt sie allein wegen der Geldgeber ab."},{"option":3,"text":"Vorab festzulegen, was einen überzeugen würde, ist ein gutes Prinzip, wenn Belege schrittweise abgetan werden. Hier gab es aber noch gar keinen geprüften Beleg, an dem eine Latte verschoben werden könnte. Die Ablehnung stützt sich von Anfang an nur auf die Quelle, nicht auf die Studie selbst."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Einträge Ad Hominem, Circumstantial Ad Hominem)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Lundh, A. u. a. (2017): Industry sponsorship and research outcome. Cochrane Database of Systematic Reviews MR000033","oeffentlich":true,"doi":"10.1002/14651858.MR000033.pub3","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"774c5c4c62ce3ae7"}},{"id":"qx-d1-002","clusterId":"D","werkstueckRef":"D.1.1","stufe":1,"question":"Welche Antwort bleibt beim Argument der Chemikerin und weicht nicht auf die Person aus?","scenario":"In einer Online-Diskussion über die Sicherheit eines neuen Haushaltsreinigers antwortet jemand auf den Hinweis einer Chemikerin, der Wirkstoff sei laut Prüfbericht in der üblichen Dosierung unbedenklich.","options":["„Du behauptest also, man könne den Reiniger in jeder beliebigen Menge völlig ohne Risiko verwenden?“","„Lass uns den Prüfbericht gemeinsam ansehen: Wie wurde die Dosierung festgelegt, und welche Testbedingungen wurden verwendet?“","„Natürliche Mittel wie Essig sind verträglicher als jede Chemie, deshalb sollten wir diesen Reiniger gar nicht erst nutzen.“","„Wenn wir jedem Wirkstoff in kleiner Dosis trauen, gilt bald jede Chemikalie als unbedenklich, und niemand kontrolliert mehr etwas.“"],"correctIndex":1,"explanation":"Ob ein Wirkstoff in der üblichen Dosierung unbedenklich ist, hängt an den Daten und der Methode des Prüfberichts, nicht an der Person, die darauf hinweist. Die Antwort, die nach Dosierung und Testbedingungen fragt, prüft genau das und bleibt bei der Sache. Die Glaubwürdigkeit einer Quelle zu hinterfragen kann legitim sein, widerlegt das Argument aber nicht automatisch. Die anderen Antworten greifen die Chemikerin zwar nicht persönlich an, bleiben aber trotzdem nicht bei ihrem Argument. Die erste unterstellt ihr eine Aussage über beliebige Mengen, obwohl sie ausdrücklich von der üblichen Dosierung sprach. Die zweite setzt den Glauben an das Natürliche an die Stelle der Daten. Die dritte warnt vor einer Folge, die aus ihrem Hinweis nicht folgt.","coreRule":"⚡ Prüfe, was gesagt wird, nicht, wer es sagt: Beschimpfung, Motivunterstellung und Heuchelei-Vorwurf führen weg von der Sache und hin zur Person.","quote":"Die logische Gültigkeit oder Falschheit eines Arguments hängt niemals von den Eigenschaften der Person ab, die es ausspricht.","quoteLabel":"Merksatz:","beleg":"Werkstück D.1.1 (Kontext & Tiefe: abusive, Tu quoque, circumstantial)","status":"entwurf","kurz":"Ob der Wirkstoff in der üblichen Dosierung unbedenklich ist, entscheiden Daten und Methode des Prüfberichts, nicht die Person, die darauf hinweist. Wer nach Dosierung und Testbedingungen fragt, prüft genau das.","prueffrage":"Worauf bezieht sich die Antwort: auf das, was im Bericht steht, oder auf die Person, die ihn nennt?","rueckmeldung":[{"option":0,"text":"Dass die Menge eine Rolle spielt, stimmt. Die Chemikerin sprach aber ausdrücklich von der üblichen Dosierung, nicht von jeder beliebigen Menge. Die Antwort widerlegt daher eine Behauptung, die sie gar nicht aufgestellt hat."},{"option":2,"text":"Vorsicht gegenüber Chemie wirkt vernünftig. „Natürlich“ ist aber kein Beleg für Verträglichkeit, und der Prüfbericht bleibt unbeachtet. Das Gattungsurteil ersetzt hier die Daten, mit denen sich der Hinweis prüfen ließe."},{"option":3,"text":"Kontrolle ist wichtig, und blindes Vertrauen in Dosisangaben wäre falsch. Der Hinweis der Chemikerin verlangt das aber nicht: Er bezieht sich auf einen einzelnen Prüfbericht. Die ausgemalte Folge folgt aus ihm nicht."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Einträge Ad Hominem, Circumstantial Ad Hominem, Tu Quoque)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"4f7b1a227bdcf15f"}},{"id":"qx-d1-003","clusterId":"D","werkstueckRef":"D.1.1","stufe":3,"question":"Welche Reaktion ist die sachlich richtige Antwort auf diese Lage?","options":["Die Finanzierung ist ein Grund, die Studie besonders genau zu prüfen, aber ob die Daten stimmen, zeigt erst die Analyse von Methode und Ergebnissen.","Der Einwand ist nur zulässig, wenn der Teilnehmer zuvor seine eigenen Geldgeber offenlegt; erst danach darf man über die Studie selbst sprechen.","Wissenschaftlerinnen mit eigenem Institut sind auf ihrem Fachgebiet kompetent; ihre Studie sollte man daher so lange akzeptieren, bis ein Fachkollege widerspricht.","Zuerst sollte der Ton versachlicht werden, denn erst wenn alle ruhig diskutieren, lässt sich überhaupt sinnvoll über die Studie sprechen."],"correctIndex":0,"explanation":"Motive und Geldgeber zu prüfen ist legitim: Sie sind ein guter Grund für besonders kritisches Lesen. Zum Fehlschluss wird es, wenn diese Prüfung die Auseinandersetzung mit dem Argument ersetzt. Ein Interessenkonflikt beweist nicht, dass die Daten falsch sind. Das zeigt sich nur an der Analyse der Studie selbst: Ist das Argument in sich stimmig, und wird es von Beweisen gestützt? Dass der Zwischenrufer seine eigenen Geldgeber offenlegt, ändert nichts daran, was in der Studie steht. Fachkompetenz der Wissenschaftlerin ersetzt die Prüfung ebenso wenig, wie Misstrauen sie ersetzt. Und ein ruhigerer Ton hilft der Debatte, klärt aber die Frage nach der Studie nicht.","coreRule":"⚡ Die Glaubwürdigkeitsprüfung ergänzt die Prüfung des Arguments, sie ersetzt sie nie.","beleg":"Werkstück D.1.1 (Der Kipppunkt; Das Adaptive Talent)","status":"entwurf","scenario":"In einer Diskussion über ein neues Pflanzenschutzmittel stellt eine Wissenschaftlerin Studiendaten vor, nach denen das Mittel unbedenklich ist. Du erfährst, dass ihr Institut vom Hersteller finanziert wird. Ein Teilnehmer ruft: „Die Studie ist damit erledigt, die Frau ist ja gekauft!“","kurz":"Ein Geldgeber ist ein guter Grund, genauer hinzusehen, widerlegt die Daten aber nicht. Der naheliegende Fehler ist, die Herkunft der Studie an die Stelle ihrer Prüfung zu setzen; ob sie stimmt, zeigt sich an Methode und Ergebnissen.","prueffrage":"Worauf stützt der Teilnehmer sein Urteil „erledigt“: auf etwas in den Daten oder allein auf den Geldgeber?","rueckmeldung":[{"option":1,"text":"Offenlegung von Interessen ist hilfreich, und sie gilt für alle Beteiligten. Als Bedingung vor der Sachdiskussion trägt sie aber nicht: Was in der Studie steht, bleibt davon unberührt und lässt sich auch ohne diese Vorleistung prüfen."},{"option":2,"text":"Fachkompetenz spricht für die Wissenschaftlerin, ersetzt aber die Prüfung der Studie genauso wenig, wie Misstrauen es tut. Auf einen Widerspruch von Fachkollegen zu warten, verschiebt die Prüfung nur, und der Interessenkonflikt bleibt ein Grund für genaues Lesen."},{"option":3,"text":"Ein ruhigerer Ton hilft der Debatte, das stimmt. Die Frage, ob die Daten tragen, bleibt davon jedoch unberührt: Sie lässt sich nur an der Studie selbst klären, und das geht auch in einer hitzigen Runde."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Circumstantial Ad Hominem)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Lundh, A. u. a. (2017): Industry sponsorship and research outcome. Cochrane Database of Systematic Reviews MR000033","oeffentlich":true,"doi":"10.1002/14651858.MR000033.pub3","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"8db4075b51bd7788"}},{"id":"qx-d1-004","clusterId":"D","werkstueckRef":"D.1.1","stufe":4,"question":"Was ist an deiner Folgerung das Problem?","scenario":"Dein Bekannter sagt: „Schau dir diesen heißen Sommer an – der Klimawandel ist real!“ Du antwortest: „Das ist Wetter, nicht Klima – also ist wohl nichts dran an der Erwärmung.“","options":["Nichts: Wer einen Fehler im Argument nachweist, hat damit gezeigt, dass die behauptete Schlussfolgerung falsch ist.","Dein Hinweis ist selbst falsch: Wetter und Klima zu verwechseln ist eine zulässige Abkürzung und kein Denkfehler.","Dein Hinweis ist selbst ein Fehlschluss: Wer einem Argument ein Etikett anheftet, ohne es zu begründen, widerlegt damit nichts.","Dein Hinweis trifft nur das Argument: Ein Fehler darin macht die Behauptung des Bekannten nicht automatisch falsch."],"correctIndex":3,"explanation":"Der Bekannte verwechselt Wetter und Klima, sein Argument ist also fehlerhaft. Ein fehlerhaftes Argument stützt seine Behauptung nicht, aber es widerlegt sie auch nicht: Ob eine Behauptung stimmt, hängt von der Sache und den Belegen ab, nicht davon, wer sie vorbringt oder wie schlecht das Argument dafür gebaut ist. Ob sie stimmt, zeigt erst die Prüfung der Sache selbst, etwa langjährige Temperaturreihen statt eines einzelnen Sommers. Wer aus dem Fehler schließt, an der Erwärmung sei nichts dran, springt zu früh. Dein Hinweis auf die Verwechslung ist berechtigt, aber er beantwortet nur die Frage, ob das Argument taugt, nicht die Frage, ob die Behauptung stimmt.","coreRule":"⚡ Ein Fehler im Argument widerlegt nicht die Behauptung – prüfe die Sache selbst.","beleg":"Werkstück D.1.1 (Ad Hominem), Abschnitte „Kontext & Tiefe“ und „Der Kipppunkt“; keine Fußnote","status":"zurueckgezogen","kurz":"Der Hinweis auf die Verwechslung von Wetter und Klima ist berechtigt, trifft aber nur das Argument. Dass ein Argument schlecht ist, macht die Behauptung nicht falsch: Sie kann trotzdem stimmen, und das zeigt erst die Prüfung der Sache selbst.","prueffrage":"Was sagen langjährige Temperaturreihen, wenn du sie neben diesen einen Sommer legst?","rueckmeldung":[{"option":0,"text":"Einen Fehler im Argument zu finden, fühlt sich wie eine Widerlegung an. Er zeigt aber nur, dass dieser Grund nicht trägt. Die Behauptung kann aus einem schlechten Grund vorgebracht werden und trotzdem stimmen."},{"option":1,"text":"Hier liegt die Abkürzung nahe, weil beides mit dem Himmel über uns zu tun hat. Dein Hinweis ist aber berechtigt: Ein einzelner heißer Sommer ist Wetter, Klima meint langfristige Entwicklungen. Das Problem liegt im Schluss, den du daraus ziehst."},{"option":2,"text":"Ein bloßes Etikett widerlegt tatsächlich nichts. Dein Hinweis ist aber keines, sondern begründet: Ein einzelner Sommer sagt über das Klima wenig. Das Problem liegt beim Schluss auf die Erwärmung, nicht beim Hinweis selbst."}],"familie":"fehlschluss-macht-nichts-falsch","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Validity and Soundness“ (anonymer Verfasser)","oeffentlich":true,"url":"https://iep.utm.edu/val-snd/","abruf":"2026-10-12"},{"typ":"doi","kurz":"IPCC (2021): Summary for Policymakers. Climate Change 2021: The Physical Science Basis, WG I, AR6","oeffentlich":true,"doi":"10.1017/9781009157896.001","seite":"Abschnitt A.1.2","abruf":"2026-10-04"},{"typ":"literatur","kurz":"Novella, S. u. a. (2018): The Skeptics' Guide to the Universe, Kap. 10, Abschnitt „Fallacy Fallacy“ (E-Book ohne Seitenzahlen)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"streichen","pruefsumme":"d0b7a61df01a82aa"}},{"id":"qx-d1-005","clusterId":"D","werkstueckRef":"D.1.2","stufe":1,"question":"Welche Antwort prüft am besten, ob die Erwiderung deines Bruders deinen Vorschlag trifft?","scenario":"Du sagst beim Familienessen: „Ich fände es schön, wenn wir abends ab und zu ohne Handys essen.“ Dein Bruder erwidert: „Du willst uns also das Handy verbieten und alle zurück in die Steinzeit schicken?“","options":["Ich würde fragen: „Habe ich ein Verbot gefordert?“ Damit lege ich meinen tatsächlichen Satz neben seine Wiedergabe und vergleiche, ob beide zusammenpassen.","Ich würde fragen: „Wie oft liegen bei uns beim Essen eigentlich Handys auf dem Tisch?“ Damit prüfe ich, wie groß das Problem überhaupt ist.","Ich würde fragen: „Gibt es Untersuchungen, ob gemeinsames Essen ohne Handys etwas bringt?“ Damit prüfe ich, ob mein Vorschlag sachlich begründet ist.","Ich würde fragen: „Wer achtet darauf, dass sich alle daran halten, und was passiert bei Verstößen?“ Damit prüfe ich, ob mein Vorschlag im Alltag umsetzbar ist."],"correctIndex":0,"explanation":"Aus „ab und zu ohne Handys essen“ macht dein Bruder „Handy verbieten“ und „zurück in die Steinzeit“. Er widerlegt damit nicht deinen Vorschlag, sondern eine übertriebene Version davon: ein Strohmann. Am besten prüfst du das, indem du deinen Satz wörtlich neben seine Wiedergabe legst und fragst, ob sie zusammenpassen. So wird sichtbar, dass er auf etwas antwortet, das du nicht gesagt hast. Wie verbreitet Handys am Tisch sind, sagt nichts darüber, ob dein Bruder dich richtig wiedergibt. Ob handyfreie Mahlzeiten etwas bringen, prüft den Vorschlag selbst, nicht seine Erwiderung. Die Umsetzbarkeit ist eine spätere Frage, die sich erst stellt, wenn klar ist, worüber ihr überhaupt redet.","coreRule":"⚡ Prüfe, ob widerlegt wird, was gesagt wurde, oder nur, was sich bequem widerlegen lässt.","quote":"Du fühlst den Drang zu sagen: „Aber das habe ich doch gar nicht gesagt!“","quoteLabel":"Merksatz:","beleg":"Werkstück D.1.2 (Kernidee; Formen des Strohmanns: Übertreibung; Red Flags)","status":"entwurf","kurz":"Aus „ab und zu“ wurde bei deinem Bruder „verbieten“ und „Steinzeit“. Das bekämpft eine übertriebene Version deines Vorschlags, nicht ihn selbst. Das siehst du, wenn du deinen Satz wörtlich neben seine Wiedergabe legst und fragst, ob beide zusammenpassen.","prueffrage":"Welche Abende und wie viele Mahlzeiten wären von deinem Vorschlag überhaupt betroffen?","rueckmeldung":[{"option":1,"text":"Wie oft Handys beim Essen auf dem Tisch liegen, zeigt, wie groß das Thema bei euch ist. Ob dein Bruder deinen Vorschlag richtig wiedergegeben hat, lässt sich daran aber nicht ablesen."},{"option":2,"text":"Mit Untersuchungen prüfst du, ob handyfreie Mahlzeiten etwas bringen, also den Vorschlag selbst. Dein Bruder hat aber auf eine andere Aussage geantwortet, und genau die bleibt dabei ungeprüft."},{"option":3,"text":"Wer kontrolliert und was bei Verstößen passiert, ist eine praktische Frage, die erst später dran ist. Zuerst muss klar sein, was du überhaupt vorgeschlagen hast, denn „Verstöße“ setzen schon ein Verbot voraus."}],"familie":"strohmann-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Straw Man)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Bowell, T.; Kemp, G. (2002): Critical Thinking: A Concise Guide. London: Routledge","oeffentlich":false,"seite":"S. 144 (laut Landkarte-Fußnote gl-d-strohmann)"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"f713b4faca185162"}},{"id":"qx-d1-006","clusterId":"D","werkstueckRef":"D.1.2","stufe":2,"question":"Welche Rückfrage prüft am besten, ob dieser Text eine tragfähige Begründung für die Methode liefert?","scenario":"In einem Werbetext für eine alternative Methode steht: „Die Schulmedizin sieht den Menschen nur als Maschine und interessiert sich nicht für die Seele. Wir dagegen behandeln den ganzen Menschen.“ Eine Leserin findet den Text überzeugend und überlegt, die Methode auszuprobieren.","options":["Ob die Schulmedizin so arbeitet, wie der Text behauptet, und was für die eigene Methode belegt wird","Wie viele Menschen den Text gelesen haben und ob sie die Methode später selbst ausprobiert haben","Wie lange es die Methode schon gibt und wer sie vor vielen Jahren ursprünglich entwickelt hat","Welche Berufsgruppe den Text verfasst hat und ob sie am Verkauf der Methode etwas verdient"],"correctIndex":0,"explanation":"Der Text baut ein Zerrbild der Schulmedizin auf und widerlegt dann dieses Zerrbild: Er ignoriert die umfangreiche psychosomatische Forschung und die Bemühungen vieler Ärzte um eine ganzheitliche Betrachtung, um die eigene „alternative“ Methode als einzig empathische darzustellen. Das ist ein Strohmann-Argument. Daraus folgt für die Leserin: Auch ein widerlegtes Zerrbild sagt noch nichts darüber, ob die eigene Methode wirkt. Die richtige Rückfrage prüft deshalb beides: ob die Darstellung des Gegners fair ist und ob für die eigene Methode überhaupt etwas belegt wird. Die anderen Fragen betreffen Beliebtheit, Alter, Herkunft oder Interessen und lassen offen, ob die Methode wirkt.","coreRule":"⚡ Wer die Gegenseite nur als Zerrbild zeigt, hat über die eigene Sache noch nichts bewiesen.","beleg":"Werkstück D.1.2 (Anwendung & Relevanz: In der Pseudomedizin)","status":"entwurf","kurz":"Der Text widerlegt nur ein Zerrbild der Schulmedizin, und das sagt noch nichts darüber, ob die eigene Methode wirkt. Deshalb muss man beides prüfen: ob der Gegner fair dargestellt ist und ob für die Methode selbst etwas belegt wird.","prueffrage":"Wie viele Sätze des Textes handeln von der Schulmedizin, und wie viele davon, was die angebotene Methode bewirkt?","rueckmeldung":[{"option":1,"text":"Viele Leser und Ausprobierer wirken wie ein gutes Zeichen. Die Zahl sagt aber nur, wie bekannt oder beliebt der Text ist, nicht, ob die Begründung trägt oder die Methode wirkt."},{"option":2,"text":"Eine lange Geschichte wirkt vertrauenswürdig, weil sich Dinge ja bewähren könnten. Wie alt eine Methode ist und wer sie erfand, sagt aber nichts darüber, ob sie wirkt oder ob der Text fair argumentiert."},{"option":3,"text":"Wer am Verkauf verdient, hat einen Anreiz zu übertreiben, und das ist ein berechtigtes Warnsignal. Es betrifft aber nur die Quelle: Der Fehler im Text, das verzerrte Bild des Gegners, bleibt dabei unbeachtet."}],"familie":"strohmann-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Straw Man)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Bowell, T.; Kemp, G. (2002): Critical Thinking: A Concise Guide. London: Routledge","oeffentlich":false,"seite":"S. 144 (laut Landkarte-Fußnote gl-d-strohmann)"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"eaed246495b7b756"}},{"id":"qx-d1-007","clusterId":"D","werkstueckRef":"D.1.2","stufe":3,"question":"Wie reagierst du am klügsten?","scenario":"In der Teambesprechung schlägst du vor, die Wochenberichte um eine Seite zu kürzen. Ein Kollege ruft: „Du willst also jede Dokumentation abschaffen!“ Mehrere im Raum nicken, die Stimmung kippt.","options":["Die Sitzung kurz unterbrechen und den Vorschlag später schriftlich neu einreichen, damit sich die Stimmung beruhigt.","Kurz wiedergeben, wie du ihn verstanden hast, und dann in einem Satz sagen, was du tatsächlich vorgeschlagen hast.","Die Vorteile kürzerer Berichte hervorheben und zeigen, wie viel Zeit das dem Team für die eigentliche Arbeit lässt.","Zustimmen, dass Dokumentation wichtig ist, und den Vorschlag dann so abschwächen, dass er niemanden mehr stört."],"correctIndex":1,"explanation":"Der Kollege hat nicht auf deinen Vorschlag geantwortet, sondern auf eine übertriebene Fassung davon: ein Strohmann. Am wirksamsten ist es, die Verzerrung sichtbar zu machen und die Debatte zu deiner tatsächlichen Aussage zurückzuführen. Das gelingt, wenn du seine Fassung neutral zurückspiegelst und deinen Punkt klarstellst. Oft reicht diese sanfte Konfrontation schon, um den Angreifer zum Zurückrudern zu zwingen. Eine Pause mit späterem schriftlichem Nachreichen lässt die falsche Darstellung im Raum stehen. Wer nur mit Vorteilen argumentiert, antwortet auf einen Vorschlag, den die Gruppe gerade falsch verstanden hat. Ein vorauseilendes Abschwächen gibt einen Punkt auf, den niemand widerlegt hat.","coreRule":"⚡ Spiegle den Strohmann neutral zurück und führe die Debatte zu deiner tatsächlichen Aussage.","quote":"Das ist eine interessante Kritik, aber sie richtet sich nicht gegen das, was ich gesagt habe. Mein eigentlicher Punkt war...","quoteLabel":"Beispielantwort:","beleg":"Werkstück D.1.2 (Das Anti-Denkmuster: Aktivierungs-Frage)","status":"entwurf","kurz":"Der Kollege hat auf eine übertriebene Fassung deines Vorschlags geantwortet. Gibst du seine Version neutral wieder und sagst dann in einem Satz, was du vorgeschlagen hast, führst du die Debatte zurück zur Sache. Oft rudert er dann zurück.","prueffrage":"Beziehen sich die Einwände im Raum auf das, was du gesagt hast, oder auf etwas, das erst danach daraus gemacht wurde?","rueckmeldung":[{"option":0,"text":"Eine Pause kann die Stimmung beruhigen. Die verzerrte Fassung steht aber weiter im Raum, und alle gehen mit ihr auseinander. Ein späteres schriftliches Nachreichen korrigiert das Missverständnis nicht."},{"option":2,"text":"Der Zeitgewinn ist ein echtes Argument. Gerade wurde aber eine übertriebene Fassung deines Vorschlags beurteilt, nicht dein Vorschlag. Solange diese Verzerrung stehen bleibt, begründest du etwas, das die Gruppe gar nicht gehört hat."},{"option":3,"text":"Dass Dokumentation wichtig ist, stimmt und widerspricht deinem Vorschlag nicht. Ihn danach abzuschwächen, gibt aber einen Punkt auf, den niemand widerlegt hat. Die Verzerrung bleibt unkorrigiert, und der Angriff hat sich gelohnt."}],"familie":"strohmann-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Straw Man)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Bowell, T.; Kemp, G. (2002): Critical Thinking: A Concise Guide. London: Routledge","oeffentlich":false,"seite":"S. 144 und 150 (laut Landkarte-Fußnote gl-d-strohmann)"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"ad30296ffc1f9921"}},{"id":"qx-d1-008","clusterId":"D","werkstueckRef":"D.1.2","stufe":4,"question":"Was solltest du tun, bevor du Jonas’ Vorschlag kritisierst, damit du nicht dasselbe tust wie Mara?","scenario":"Kollege Jonas sagt in der Teambesprechung: „Ich würde die Kernarbeitszeit etwas lockern, damit Eltern ihre Kinder morgens in Ruhe in die Kita bringen können.“ Deine Kollegin Mara antwortet empört: „Jonas will also, dass niemand mehr pünktlich im Büro ist und alle kommen und gehen, wann sie wollen!“ Du sollst gleich selbst auf Jonas’ Vorschlag antworten und möchtest dabei fair bleiben.","options":["Jonas’ Vorschlag in seiner stärksten Form mit eigenen Worten zusammenfassen und ihn bestätigen lassen, dass du ihn richtig verstanden hast.","Offenlegen, welche eigenen Interessen du an der Kernarbeitszeit hast, und erst dann Kritik äußern, damit niemand verdeckte Motive vermutet.","Mit Daten belegen lassen, wie viele Eltern von einer Lockerung profitieren würden, und deine Kritik erst danach auf diese Zahlen stützen.","Klären, ob der Vorschlag mit den geltenden Regeln zur Arbeitszeit vereinbar ist, und deine Kritik an diesem Maßstab ausrichten."],"correctIndex":0,"explanation":"Mara hat nicht auf Jonas’ tatsächlichen Vorschlag geantwortet, sondern eine übertriebene Karikatur davon angegriffen: einen Strohmann. Das Gegenmittel ist die faire Rekonstruktion: Du gibst die Position des anderen in ihrer besten Form wieder und lässt sie bestätigen, bevor du sie kritisierst. Dann kann kein Strohmann entstehen, und deine Kritik trifft den echten Vorschlag. Eigene Interessen offenzulegen ist fair, ändert aber nichts daran, ob du Jonas richtig wiedergibst. Zahlen zum Nutzen helfen bei der Bewertung, setzen aber voraus, dass der Vorschlag richtig verstanden ist. Die Prüfung der Regeln ist ein eigener Schritt, der erst sinnvoll ist, wenn klar ist, was genau vorgeschlagen wurde.","coreRule":"⚡ Gib die Position des Gegners in ihrer stärksten Form wieder, bevor du sie kritisierst – dann kann kein Strohmann entstehen.","beleg":"Werkstück D.1.2 (Formen des Strohmanns; Verbindungen: Stahlmann-Argument; Fußnote gl-d-strohmann: Principle of Charity, Bowell/Kemp 2002)","status":"entwurf","kurz":"Maras Satz kritisiert eine Karikatur, nicht Jonas' Vorschlag. Wer vorher dessen beste Fassung mit eigenen Worten wiedergibt und bestätigen lässt, trifft mit der Kritik den echten Vorschlag und baut keinen Strohmann.","prueffrage":"Welchen Zweck nennt Jonas, und wie weit soll die Lockerung nach seinen Worten gehen?","rueckmeldung":[{"option":1,"text":"Eigene Interessen offenzulegen ist fair und schafft Vertrauen. Es sagt aber nichts darüber, ob du Jonas richtig wiedergibst, und eine verzerrte Darstellung bleibt auch mit offenen Motiven verzerrt."},{"option":2,"text":"Zahlen zum Nutzen können die Bewertung des Vorschlags verbessern. Sie setzen aber voraus, dass klar ist, was Jonas überhaupt vorschlägt; wer ihn vorher verzerrt, stützt seine Kritik auf Daten zum falschen Gegenstand."},{"option":3,"text":"Ob der Vorschlag zu den Arbeitszeitregeln passt, ist eine berechtigte Frage. Sie lässt sich aber erst sinnvoll stellen, wenn feststeht, was genau gemeint ist; „etwas lockern“ ist nicht „alle kommen, wann sie wollen“."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Straw Man)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Bowell, T.; Kemp, G. (2002): Critical Thinking: A Concise Guide. London: Routledge (Principle of Charity)","oeffentlich":false,"seite":"S. 43–47, S. 144 (laut Landkarte-Fußnote gl-d-strohmann)"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"e656553a9e395ec5"}},{"id":"qx-d1-009","clusterId":"D","werkstueckRef":"D.1.3","stufe":2,"question":"Welche Möglichkeit blendet dieser Satz aus?","scenario":"Bei einer Vereinsreform sagt der Vorsitzende: „Wer nicht Teil der Lösung ist, ist Teil des Problems.“ Du hältst den Reformplan für unausgereift, hast aber selbst noch keinen besseren Vorschlag.","options":["Dass die Reform auch ohne dein Zutun beschlossen werden kann und deine Haltung dadurch folgenlos bleibt.","Dass man den Plan kritisieren kann, ohne das Problem zu stützen, etwa weil man ihn erst verbessern will.","Dass der Vorsitzende als Amtsträger auftritt und deshalb jeden Widerspruch im Verein unterbinden möchte.","Dass es im Verein zwei Lager gibt, die man gleichberechtigt anhören müsste, damit beide Seiten ausgewogen vertreten sind."],"correctIndex":1,"explanation":"Der Satz presst die Lage in ein Entweder-oder: Wer den Plan unterstützt, ist Teil der Lösung, wer ihn nicht unterstützt, Teil des Problems. Dabei fällt unter den Tisch, dass man einen Plan für unausgereift halten kann, ohne schon eine bessere Lösung zu haben, etwa weil man ihn erst verbessern oder das Problem genauer verstehen will. Das macht niemanden zum Teil des Problems. Der Fehlschluss heißt falsches Dilemma; er funktioniert, weil Kritik an der einen Seite automatisch als Zustimmung zur anderen gedeutet wird. Ein prüfender Gegenzug ist die Frage: „Welche weiteren Möglichkeiten gibt es neben diesen beiden?“","coreRule":"⚡ Wer nur zwei Plätze anbietet, hat die übrigen Möglichkeiten schon aus dem Raum geschoben.","beleg":"Werkstück D.1.3 (Anwendung & Relevanz: Im Alltag; Red Flags; Anti-Denkmuster)","status":"entwurf","kurz":"Der Satz kennt nur „Teil der Lösung“ und „Teil des Problems“. Wer den Plan kritisiert, kann ihn aber auch erst verbessern oder das Problem genauer verstehen wollen, ohne deshalb Teil des Problems zu sein.","prueffrage":"Was genau stört dich am Reformplan, und was müsste sich ändern, damit du zustimmst?","rueckmeldung":[{"option":0,"text":"Dass die eigene Haltung folgenlos bleiben kann, ist durchaus denkbar. Darum geht es in dem Satz aber nicht: Er stellt nur zwei Positionen zur Wahl und blendet aus, dass man den Plan kritisieren kann, ohne das Problem zu stützen."},{"option":2,"text":"Eine Amtsrolle kann Druck erzeugen, und manchmal soll ein solcher Satz tatsächlich Widerspruch dämpfen. Über die Absichten des Vorsitzenden ist aber nichts bekannt; der Fehler steckt in der Form des Satzes, nicht in vermuteten Motiven."},{"option":3,"text":"Beide Seiten anzuhören klingt fair, übernimmt aber die Zweiteilung, die der Satz vorgibt. Fehlerhaft ist gerade, dass nur zwei Positionen zur Wahl stehen und andere Lösungen oder offene Fragen darin keinen Platz haben."}],"familie":"falsches-dilemma","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Einträge False Dilemma, Black-or-White)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0b11d52a73d6f4fb"}},{"id":"qx-d1-010","clusterId":"D","werkstueckRef":"D.1.3","stufe":3,"question":"Beide Aussagen sind Entweder-oder-Aussagen, aber nur eine davon ist ein Falsches Dilemma. Woran erkennst du, welche?","scenario":"Im Gemeinderat sagt ein Redner zur geplanten Umgehungsstraße: „Entweder bauen wir die Straße genau so, wie sie jetzt geplant ist, oder unser Ort erstickt im Verkehr. Wer dagegen stimmt, will den Stau.“ Auf einem Formular der Gemeinde steht dagegen die Frage: „Wurde die Gebühr bezahlt? Ja oder Nein.“","options":["Daran, ob nur zwei Möglichkeiten genannt werden: Sobald eine Aussage genau zwei Optionen gegenüberstellt, ist sie ein Falsches Dilemma, weil sie die Auswahl verengt.","Daran, ob der Sprecher eine Entscheidung verlangt: Wer eine Antwort einfordert, zwingt zur Wahl und begeht damit ein Falsches Dilemma.","Daran, ob es weitere Möglichkeiten gibt, die verschwiegen werden: Die Zweiteilung wird dann künstlich aufgezwungen und engt den Denkraum ein.","Daran, ob sich die beiden Optionen gegenseitig ausschließen: Schließt die eine die andere aus, wird eine Wahl aufgezwungen, und es liegt ein Falsches Dilemma vor."],"correctIndex":2,"explanation":"Ein echtes Dilemma gibt es nur, wenn tatsächlich nur zwei Möglichkeiten bestehen, etwa bei „Leben oder Tod“. Die Gebühr ist entweder bezahlt oder nicht, das Formular ist also unproblematisch. Beim Redner im Gemeinderat gibt es dagegen mehr Möglichkeiten: Er verschweigt sie, damit seine Variante als einzig vernünftige Wahl erscheint, und stempelt Kritik als Wunsch nach dem Stau ab. Entscheidend ist also nicht die Form „Entweder-oder“, sondern ob es wirklich keine dritte Möglichkeit gibt oder ob sie nur ausgeblendet wird. Dass nur zwei Möglichkeiten genannt werden, trifft auch auf das Formular zu, ohne dass dort ein Fehler läge. Dass sich die Optionen ausschließen, gilt für beide Aussagen und trennt sie daher nicht. Und eine Entscheidung verlangt ebenso die Frage auf dem Formular.","coreRule":"⚡ Prüfe nicht die Form „Entweder-oder“, sondern ob es wirklich keine dritte Möglichkeit gibt.","beleg":"Werkstück D.1.3 (Kontext & Tiefe: echtes Dilemma; Der Kipppunkt)","status":"entwurf","kurz":"Entscheidend ist nicht die Entweder-oder-Form, sondern ob eine dritte Möglichkeit existiert. Beim Formular gibt es keine, beim Redner dagegen schon, er blendet sie aus, damit seine Variante als einzig vernünftige Wahl erscheint.","prueffrage":"Was haben beide Aussagen gemeinsam: Verlangen beide eine Entscheidung, und klingt in beiden eine der Möglichkeiten unangenehm?","rueckmeldung":[{"option":0,"text":"Zwei Möglichkeiten werden zwar in beiden Aussagen genannt. Beim Formular stimmt die Zweiteilung aber sachlich, die Gebühr ist bezahlt oder nicht. Die bloße Zahl der Optionen sagt also noch nichts über einen Fehler."},{"option":1,"text":"Dass der Redner zu einer Entscheidung drängt, stimmt. Die Frage auf dem Formular verlangt aber ebenso eine Antwort und ist trotzdem völlig in Ordnung. Das Verlangen nach einer Wahl trennt die beiden Aussagen daher nicht."},{"option":3,"text":"Beide Aussagen stellen Optionen gegenüber, die sich ausschließen. Genau deshalb unterscheidet dieses Merkmal sie nicht: Auf dem Formular ist es ebenso gegeben, ohne dass dort ein Fehler läge. Es kommt darauf an, ob weitere Möglichkeiten bestehen."}],"familie":"falsches-dilemma","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Black-or-White)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"edd74114d8d12cc2"}},{"id":"qx-d1-011","clusterId":"D","werkstueckRef":"D.1.3","stufe":4,"question":"Wie beurteilst du diesen Einwand am besten?","scenario":"In einem Forum wird behauptet: „Bush hat nach dem 11. September 2001 gesagt: ‚Wer nicht für uns ist, ist gegen uns.‘ Das ist ein Lehrbuchbeispiel für ein Falsches Dilemma.“ Ein anderer Nutzer antwortet: „Das Zitat ist so wohl nicht korrekt. Im Transkript der Rede vor dem Kongress vom 20. September 2001 steht: ‚Either you are with us, or you are with the terrorists.‘ Dein Beispiel taugt also nichts.“","options":["Der Einwand betrifft nur den Wortlaut: Auch das Original bietet nur zwei Optionen an, daher bleibt es ein Falsches Dilemma.","Der Einwand widerlegt die Behauptung, denn mit einem ungenauen Zitat ist auch die Einordnung als Falsches Dilemma hinfällig geworden.","Der Einwand ist unerheblich, denn bei einem Beispiel für einen Fehlschluss kommt es nur auf die ungefähre Aussage an, nicht auf den genauen Wortlaut.","Der Einwand zeigt, dass der Originalsatz kein Falsches Dilemma ist, denn „mit den Terroristen“ ist inhaltlich eine andere Aussage als „gegen uns“."],"correctIndex":0,"explanation":"Zwei Dinge müssen getrennt werden: ob das Zitat stimmt und ob die Struktur ein Falsches Dilemma ist. Der Einwand prüft nur die Kongressrede vom 20. September 2001: Laut Transkript lautet der Satz dort „Either you are with us, or you are with the terrorists.“ Dem Forumssatz entspricht aber, was Bush am 6. November 2001 bei einer Pressekonferenz mit Frankreichs Präsident Chirac sagte: „You’re either with us or against us in the fight against terror.“ (so berichtet von CNN). Für die Einordnung kommt es auf den Wortlaut ohnehin nicht an: Beide Sätze bieten nur zwei Möglichkeiten an, eine dritte oder neutrale Haltung ist nicht vorgesehen. Ein ungenaues Zitat macht die Einordnung also nicht falsch, es verlangt nur, das Beispiel am Original zu belegen. Wer Fehlschlüsse benennt, sollte genau zitieren, und wer widerspricht, sollte prüfen, ob der Einwand die Kernaussage überhaupt trifft.","coreRule":"⚡ Prüfe bei einem Einwand, ob er die Struktur des Arguments trifft oder nur ein Detail wie das Zitat, und belege Beispiele am Originalwortlaut.","beleg":"Werkstück D.1.3 (Anwendung & Relevanz: In der Politik); Fn. gl-d-bush911 (Bush, Address to a Joint Session of Congress, 20.09.2001, Transkript des Weißen Hauses). Pressekonferenz mit Chirac, 6.11.2001: CNN, „You are either with us or against us“, https://edition.cnn.com/2001/US/11/06/gen.attack.on.terror/ (abgerufen 12.10.2026); wiedergegeben auch bei Monshipouri (2012): Terrorism, Security, and Human Rights, Lynne Rienner, Anm. 10.","status":"entwurf","kurz":"Der Einwand prüft nur die Kongressrede; einen fast gleichen Satz sagte Bush am 6. November 2001. Und selbst bei falschem Wortlaut bliebe es ein Falsches Dilemma: Auch der Satz der Kongressrede bietet nur zwei Möglichkeiten an.","prueffrage":"Bei welchen Gelegenheiten hat Bush ähnliche Sätze gesagt, und wo steht jeweils der genaue Wortlaut?","rueckmeldung":[{"option":1,"text":"Ein ungenaues Zitat lässt das ganze Beispiel erledigt wirken. Ob eine Aussage nur zwei Möglichkeiten zulässt, zeigt sich aber an ihrer Form, und die steckt auch im Satz der Kongressrede. Nötig ist ein genauer Beleg, nicht das Ende des Beispiels."},{"option":2,"text":"Dass der Kern gleich bleibt, stimmt: Beide Fassungen kennen nur zwei Lager. Genau deshalb lässt sich das Beispiel retten. Daraus folgt aber nicht, dass der Wortlaut egal ist; wer einen Fehlschluss anprangert, muss ihn am echten Satz belegen."},{"option":3,"text":"Die beiden Formulierungen sind tatsächlich nicht gleichbedeutend. Dieser Unterschied ändert aber nichts an der Zweiteilung: Auch „mit uns oder mit den Terroristen“ lässt keinen Platz für eine neutrale oder dritte Haltung."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"The White House (2001): President Declares „Freedom at War with Fear“, Address to a Joint Session of Congress and the American People, 20.09.2001","oeffentlich":true,"url":"https://georgewbush-whitehouse.archives.gov/news/releases/2001/09/20010920-8.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag False Dilemma)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"a099aa21283a357d"}},{"id":"qx-d1-012","clusterId":"D","werkstueckRef":"D.1.4","stufe":1,"question":"Wie solltest du auf das Argument deines Onkels am besten reagieren?","scenario":"Ein berühmter Literatur-Nobelpreisträger erklärt in einem Interview, ein neuer Impfstoff sei unsicher. Dein Onkel meint: „Dem Mann sollte man glauben, er hat schließlich einen Nobelpreis.“ Studien zum Impfstoff kennt dein Onkel nicht.","options":["Du fragst, ob der Preisträger in der Impfstoffforschung Fachwissen hat und welche Daten er vorlegt, denn das Gewicht einer Aussage hängt an Zuständigkeit und Belegen.","Du fragst, ob der Preis zu Recht vergeben wurde, denn nur dann kann man den Aussagen des Preisträgers vertrauen.","Du fragst, ob der Preisträger seine Meinung seit Jahren unverändert vertritt, denn nur eine beständige Meinung ist verlässlich.","Du fragst, ob mehrere Medien das Interview aufgegriffen haben, denn eine weit verbreitete Aussage ist besser abgesichert."],"correctIndex":0,"explanation":"Ein Preis belegt Können nur in dem Fach, in dem er erworben wurde. Wer Literatur auf Weltklasseniveau beherrscht, ist deshalb noch kein Fachmann für Impfstoffe. Ob eine Aussage über einen Impfstoff stimmt, entscheiden Daten aus Studien, nicht der Name dessen, der sie ausspricht. Dein Onkel ersetzt hier den Beweis durch einen Verweis auf eine Person, und zwar auf eine, deren Fachgebiet gar nicht zur Frage passt. Die beste Reaktion fragt deshalb nach Zuständigkeit und nach Belegen. Ob der Preis zu Recht vergeben wurde, ändert nichts daran, dass er für ein anderes Fach vergeben wurde. Eine seit Jahren gleiche Meinung macht sie nicht richtiger. Und wie weit ein Interview verbreitet ist, sagt nichts darüber, ob es stimmt.","coreRule":"⚡ Ein Rang beweist nur etwas in dem Fach, in dem er erworben wurde.","quote":"Er ersetzt den **Beweis (die Daten)** durch einen **Verweis (den Experten)**.","quoteLabel":"Merksatz:","beleg":"Werkstück D.1.4 (Kernidee: Hauptformen des Fehlschlusses)","status":"entwurf","kurz":"Ein Nobelpreis belegt Können nur in dem Fach, in dem er verliehen wurde, und Literatur macht niemanden zum Impfstoff-Experten. Über die Aussage entscheiden Studiendaten, nicht der Name; deshalb fragst du nach Zuständigkeit und Belegen.","prueffrage":"Wofür wurde der Preis verliehen, und wer hat den Impfstoff bisher in Studien untersucht?","rueckmeldung":[{"option":1,"text":"Ob der Preis zu Recht vergeben wurde, lässt sich prüfen, ändert aber nichts: Er wurde für Literatur vergeben, nicht für Impfstoffforschung. Auch ein verdienter Preis macht seinen Träger nicht zum Fachmann für ein anderes Gebiet."},{"option":2,"text":"Eine Meinung, die jemand seit Jahren unverändert vertritt, wirkt gefestigt. Beständigkeit sagt aber nur, dass sie gleich geblieben ist, nicht, dass sie stimmt. Auch ein jahrelang wiederholter Irrtum bleibt ein Irrtum."},{"option":3,"text":"Wenn viele Medien ein Interview aufgreifen, wirkt die Aussage gewichtig. Reichweite zeigt aber nur, dass über sie gesprochen wird. Ob sie stimmt, hängt weiterhin an Zuständigkeit und Daten, nicht an der Zahl der Berichte."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Appeal to Authority)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"862b70dc4de762d9"}},{"id":"qx-d1-013","clusterId":"D","werkstueckRef":"D.1.4","stufe":2,"question":"Welche Rückfrage bringt die Debatte am besten weiter?","scenario":"In einer Debatte über Vitamin C und Krebs stellst du fest, dass es dafür keine robusten Belege aus kontrollierten Studien gibt. Dein Gegenüber antwortet: „Linus Pauling, ein zweifacher Nobelpreisträger, hat hochdosiertes Vitamin C gegen Krebs vehement vertreten. Willst du es etwa besser wissen als er?“","options":["Welche Gründe könnte die Person haben, diese Behauptung zu vertreten, und wer hätte davon einen Vorteil?","Welche Daten hat die Person vorgelegt, und lassen sich diese in kontrollierten Studien bestätigen?","Wurde die Person für ihre früheren Leistungen zu Recht ausgezeichnet, und gilt sie in ihrem Fach als herausragend?","Wie lange vertritt die Person die Behauptung schon, und hat sie sie in dieser Zeit je geändert?"],"correctIndex":1,"explanation":"Der Einwand setzt eine Person an die Stelle der Daten. Paulings Nobelpreise waren für Chemie (1954) und Frieden (1962), nicht für Medizin. Entscheidend ist, was kontrollierte Studien zeigen: Gegen fortgeschrittenen Krebs half hochdosiertes Vitamin C zum Einnehmen nicht (Moertel u. a. 1985); Infusionen mit weit höheren Blutspiegeln werden noch erforscht. Die beste Antwort lenkt daher von der Person zur Evidenz: Welche Daten gibt es, und halten sie einer Prüfung stand? Man kann jemanden respektieren und trotzdem verlangen, dass die Behauptung durch Daten gedeckt ist. Welche Motive jemand hat, erklärt vielleicht einen Irrtum, prüft die Behauptung aber nicht. Ob die Ehrungen verdient waren, ändert nichts daran, dass sie kein Beleg für diese Behauptung sind. Und wie lange jemand an einer Behauptung festhält, sagt nichts über ihre Richtigkeit.","coreRule":"⚡ Respekt vor der Person ersetzt nicht den Blick auf die Daten.","beleg":"Werkstück D.1.4 (Einstiegsszene); Fn. gl-d-pauling (Nobelstiftung: Chemie 1954, Frieden 1962; Moertel u. a. 1985, NEJM 312(3), S. 137–141; Padayatty u. a. 2004; NCI (Infusionen))","status":"entwurf","kurz":"Der Einwand ersetzt Daten durch einen berühmten Namen. Weiter kommt die Debatte mit der Frage, welche Daten es gibt und ob sie in kontrollierten Studien standhalten, denn Ansehen, auch in anderen Fächern, belegt die Behauptung nicht.","prueffrage":"Wofür genau hat Pauling seine beiden Nobelpreise bekommen?","rueckmeldung":[{"option":0,"text":"Nach Motiven zu fragen wirkt gründlich, richtet den Blick aber wieder auf die Person. Warum jemand etwas vertritt, erklärt vielleicht einen Irrtum, prüft die Behauptung selbst aber nicht."},{"option":2,"text":"Respekt vor Paulings Leistungen ist berechtigt, doch seine Preise gingen für Chemie und Frieden, nicht für Medizin. Selbst verdiente Ehrungen sind kein Beleg für diese Behauptung."},{"option":3,"text":"Wie lange jemand an einer Behauptung festhält, sagt etwas über die Person, nicht über deren Richtigkeit. Auch lange vertretene Behauptungen müssen sich an Daten messen lassen."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Moertel, C. G. u. a. (1985): High-dose vitamin C versus placebo in the treatment of patients with advanced cancer who have had no prior chemotherapy. NEJM 312(3), 137–141","oeffentlich":true,"doi":"10.1056/NEJM198501173120301","url":"https://pubmed.ncbi.nlm.nih.gov/3880867/","abruf":"2026-10-12"},{"typ":"url","kurz":"National Cancer Institute: Intravenous High-Dose Vitamin C (PDQ®), Fachfassung, Stand 13.05.2025","oeffentlich":true,"url":"https://www.cancer.gov/about-cancer/treatment/cam/hp/vitamin-c-pdq","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Appeal to Authority)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"9b5834dfef01fa15"}},{"id":"qx-d1-014","clusterId":"D","werkstueckRef":"D.1.4","stufe":3,"question":"Ist dein Vertrauen in Hausarzt und Pilotin schon derselbe Fehler wie das Argument deines Bekannten, und wo liegt der Unterschied?","scenario":"Du lässt dich vom Hausarzt beraten, ohne sein Diplom zu prüfen, und vertraust der Pilotin, ohne ihre Lizenz zu kontrollieren. Später verteidigt ein Bekannter eine Gesundheitsbehauptung mit dem Satz: „Der Mann ist Professor, wer bist du, das zu bezweifeln?“ Dir fällt auf, dass du in beiden Fällen Fachleuten vertraust.","options":["Ja, jedes Vertrauen ohne eigene Prüfung ist ein Fehlschluss, weil man dabei die Evidenz durch eine Person ersetzt.","Nein, der Unterschied liegt darin, dass dein Vertrauen auf Fachleute zielt, die einen guten Ruf haben, sein Argument aber nicht.","Nein, der Fehler beginnt erst, wenn du die Aussage eines Fachmanns durch eine zweite Meinung überprüfst, weil du ihm dann misstraust.","Nein, dein Vertrauen ist eine nützliche Abkürzung; fehlerhaft wird es, sobald die Person als Beweis dient und Nachfragen nach den Belegen verboten werden."],"correctIndex":3,"explanation":"Wir können nicht alles selbst wissen. Vertrauen an (hoffentlich) evidenzbasierte Fachleute zu delegieren ist die Grundlage unserer arbeitsteiligen Gesellschaft. Dein Vertrauen bleibt ein Wegweiser zur Evidenz: Du könntest nachfragen und die Belege würden der Prüfung standhalten. Zum Fehlschluss wird es, wenn die Person an die Stelle der Daten tritt und die Frage „Was weißt du?“ durch „Wer bist du, das zu bezweifeln?“ ersetzt wird. Dann dient die Autorität nicht mehr als Hinweis auf Belege, sondern als Totschlagargument. Eine legitime Expertenmeinung wird dabei zum unfehlbaren Beweis, der jede Nachfrage verbietet (Autorität als Dogma). Reputation ist nicht Evidenz. Entscheidend ist nicht, ob du selbst alles prüfst, sondern ob Nachfragen nach den Belegen erlaubt bleiben.","coreRule":"⚡ Vertrauen in Fachleute ist klug – solange die Frage nach der Evidenz erlaubt bleibt.","quote":"","quoteLabel":"","beleg":"Werkstück D.1.4 (Kontext & Tiefe: Logik vs. Heuristik; Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","kurz":"Vertrauen in Fachleute ist eine sinnvolle Abkürzung, solange du nachfragen könntest und die Belege standhielten. Zum Fehlschluss wird es, wenn die Person die Belege ersetzt und Nachfragen als Anmaßung gelten.","prueffrage":"Woher könntest du erfahren, ob der Rat deines Hausarztes trägt, ohne selbst Medizin studiert zu haben?","rueckmeldung":[{"option":0,"text":"Dass eine Person die Belege ersetzt, ist tatsächlich das Kernproblem. Aber nicht jedes Vertrauen ohne eigene Prüfung tut das: Solange Nachfragen möglich bleiben, ist es eine sinnvolle Arbeitsteilung und kein Fehlschluss."},{"option":1,"text":"Ein guter Ruf kann auf Belege hindeuten, trägt als Unterscheidung aber nicht: Auch der Bekannte beruft sich auf einen Titel. Entscheidend ist, ob die Person zur Evidenz führt oder sie ersetzt und Nachfragen verbietet."},{"option":2,"text":"Eine zweite Meinung einzuholen ist kein Misstrauen, sondern genau das Nachfragen, das gesundes Vertrauen aushält. Fehlerhaft wird es im umgekehrten Fall, wenn Nachfragen unterbunden werden."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Appeal to Authority)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"1264ddb4e7691516"}},{"id":"qx-d1-015","clusterId":"D","werkstueckRef":"D.1.4","stufe":4,"question":"Was ist an dieser Begründung fehlerhaft?","scenario":"Im Netz heißt es: „Dr. Müller ist ein mutiger Abtrünniger, den die ‚Mainstream-Wissenschaft‘ mundtot macht. Gerade weil er den Fachleuten widerspricht, müssen seine Thesen stimmen.“","options":["Sie ersetzt Belege durch die Mehrheit, denn sie hält die Thesen für wahr, weil viele Menschen ihnen glauben.","Sie ersetzt Belege durch fehlende Gegenbeweise, denn sie hält die Thesen für wahr, weil niemand sie widerlegt hat.","Sie ersetzt Belege durch die Person Müllers, denn Widerspruch allein beweist nichts über seine Thesen.","Sie dreht sich im Kreis, denn sie stützt die Thesen auf Müllers Glaubwürdigkeit und diese auf die Thesen."],"correctIndex":2,"explanation":"Auch die Umkehrung des Autoritätsarguments ist ein Fehlschluss: Statt Daten wird die Person des „mutigen Abtrünnigen“ als Beweis angeführt. Dass jemand der Fachgemeinschaft widerspricht, macht seine Thesen weder wahr noch falsch. Entscheidend bleibt, welche Belege er vorlegt und wie die gesamte Fachgemeinschaft sie bewertet. Die Begründung beruft sich nicht auf eine Mehrheit, sondern gerade auf den Außenseiter, der gegen die Fachleute steht. Sie stützt sich auch nicht darauf, dass niemand die Thesen widerlegt hätte, sondern macht den Widerspruch der Fachleute selbst zum Beleg. Ein Kreis schließt sich ebenfalls nicht, denn die Begründung läuft nur in eine Richtung: von Müllers Rolle zu seinen Thesen.","coreRule":"⚡ Widerspruch zum Konsens ist kein Beweis – auch der Außenseiter braucht Daten.","beleg":"Werkstück D.1.4 (Kontext & Tiefe: Die Autoritäts-Umkehrung; Red Flags)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Dass jemand den Fachleuten widerspricht, sagt nichts darüber, ob seine Thesen stimmen. Der Fehler besteht darin, die Rolle des „mutigen Abtrünnigen“ als Beweis zu nehmen, statt zu fragen, welche Belege er vorlegt und wie die Fachgemeinschaft sie bewertet.","prueffrage":"Was erfährst du aus dem Beitrag über den Inhalt von Müllers Thesen?","rueckmeldung":[{"option":0,"text":"Eine Mehrheit ist tatsächlich kein Wahrheitsbeweis. Hier aber steht gerade keine Mehrheit hinter den Thesen: Die Begründung beruft sich auf einen Einzelnen, der den meisten Fachleuten widerspricht."},{"option":1,"text":"Fehlende Gegenbeweise wären als Begründung tatsächlich zu dünn. Im Text steht aber nichts davon, dass niemand die Thesen widerlegt hätte. Der Widerspruch der Fachleute wird vielmehr selbst zum vermeintlichen Beleg gemacht."},{"option":3,"text":"Ein Zirkel wäre es, wenn die Thesen die Glaubwürdigkeit stützten und die Glaubwürdigkeit wiederum die Thesen. Hier läuft der Gedanke nur in eine Richtung: von Müllers Rolle als Abtrünnigem zu seinen Thesen."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Appeal to Authority)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"ae2a266ba82aed0d"}},{"id":"qx-d1-016","clusterId":"D","werkstueckRef":"D.1.5","stufe":1,"question":"Wie bewertest du den Gegenvorwurf deines Mitbewohners im Hinblick auf deine Kritik?","scenario":"Du sprichst deinen Mitbewohner darauf an, dass er ständig Geräte unnötig laufen lässt. Er kontert: „Du lässt doch selbst dauernd das Licht im Flur brennen!“","options":["Er ändert nichts am Kern deiner Kritik, denn ob der Vorwurf an dich stimmt, ist für die Frage seines Stromverbrauchs irrelevant.","Er entkräftet deine Kritik vollständig, denn wer selbst gegen die Regel verstößt, kann sie bei anderen nicht mehr einfordern.","Er entkräftet deine Kritik teilweise, denn ein inkonsequenter Kritiker hat auch das schwächere Argument.","Er macht deine Kritik unbrauchbar, denn du hättest sie zuerst auf dein eigenes Verhalten anwenden müssen."],"correctIndex":0,"explanation":"Das ist ein Tu quoque („du auch“): Ob eine Kritik zutrifft, hängt von ihrer Logik und den Belegen ab, nicht davon, ob der Sprecher selbst konsequent handelt. Ob dein Mitbewohner unnötig Strom verbraucht, entscheidet sich an seinem Verhalten, auch wenn du im Flur das Licht brennen lässt. Dein Licht verdient vielleicht ein eigenes Gespräch, beantwortet aber nicht die Frage, ob er zu viel Strom verbraucht.","coreRule":"⚡ Ob jemand selbst danach lebt, entscheidet nicht, ob seine Aussage stimmt.","quote":"Ein Mörder, der sagt „Morden ist falsch“, hat immer noch Recht.","quoteLabel":"Zum Weiterdenken:","beleg":"Werkstück D.1.5 (Kernidee; Kontext & Tiefe: Logische Ungültigkeit)","status":"entwurf","kurz":"Ob dein Mitbewohner zu viel Strom verbraucht, zeigt sein eigenes Verhalten, nicht dein Flurlicht. Der Gegenvorwurf misst die Kritik an deiner Konsequenz statt an den Belegen; dein Licht verdient vielleicht ein eigenes Gespräch, beantwortet die Frage aber nicht.","prueffrage":"Welche Geräte lässt dein Mitbewohner laufen, wie lange, und wie viel Strom verbrauchen sie dabei?","rueckmeldung":[{"option":1,"text":"Wer selbst gegen eine Regel verstößt, wirkt als Kritiker schnell unglaubwürdig, das macht den Gegenvorwurf so griffig. Ob dein Mitbewohner zu viel Strom verbraucht, hängt aber nicht davon ab, was du tust; entkräftet wird deine Kritik dadurch nicht."},{"option":2,"text":"Ein Kritiker, der selbst nicht konsequent ist, wirkt angreifbarer, und daher klingt „teilweise“ vernünftig. Wie stark das Argument ist, hängt aber an Logik und Belegen, nicht an der Konsequenz des Sprechers."},{"option":3,"text":"Dein Flurlicht darf durchaus zur Sprache kommen, und etwas Selbstprüfung schadet nie. Die Kritik braucht dafür aber keine Vorbedingung: Ob er zu viel Strom verbraucht, klärt sich unabhängig davon, was du selbst tust."}],"familie":"du-auch-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Tu Quoque)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"08324f62bee0b379"}},{"id":"qx-d1-017","clusterId":"D","werkstueckRef":"D.1.5","stufe":2,"question":"Was ist die beste Reaktion von A auf diesen Konter?","scenario":"In einer Diskussion sagt A: „Euer Land lässt Menschen in Haft schlecht behandeln, das muss sich ändern.“ B antwortet sofort: „Und was ist mit eurer Polizeigewalt? Darüber redet ihr natürlich nie!“ Der Vorwurf der Polizeigewalt gegen das Land von A trifft tatsächlich zu; zu den Haftbedingungen im eigenen Land sagt B aber nichts.","options":["A wertet das Schweigen von B zu den Haftbedingungen als Eingeständnis und hält die Kritik damit für bewiesen, weil ein unbestrittener Vorwurf als zugegeben gilt.","A erkennt die Polizeigewalt als ernstes, eigenes Thema an, bleibt aber bei den Haftbedingungen, weil der Gegenvorwurf die ursprüngliche Kritik nicht entkräftet.","A entschuldigt sich für den Ton der Kritik und bittet B, das Gespräch sachlich neu zu beginnen, weil ein Austausch ohne gegenseitige Vorwürfe besser gelingt.","A stellt die Kritik zurück und kümmert sich zuerst um die Polizeigewalt im eigenen Land, weil man erst vor der eigenen Tür kehren sollte."],"correctIndex":1,"explanation":"Dass der Gegenvorwurf zutrifft, ändert nichts an der Gültigkeit der ursprünglichen Kritik: Er verdient eine eigene Diskussion, entkräftet den ersten Punkt aber nicht. Diese Ablenkung nennt man Whataboutism, eine Form des „Du auch“-Fehlschlusses: Er verschiebt das Gespräch von der Sachebene auf die Frage, ob der Sprecher moralisch konsistent ist. Das Ziel ist oft nicht, das eigene Handeln zu rechtfertigen, sondern den Kritiker zum Schweigen zu bringen und ein Patt zu erzeugen. Am besten erkennt man das andere Problem an, trennt es aber vom ersten und kehrt zur offenen Frage zurück. Dass B zu den Haftbedingungen schweigt, ist kein Eingeständnis: Ob die Kritik stimmt, entscheidet sich an den Haftbedingungen selbst. Eine Entschuldigung für den Ton würde nichts klären, denn um den Ton geht es im Konter gar nicht. Und mit der Kritik zu warten, bis das eigene Haus in Ordnung ist, hieße, dass sich beide Seiten gegenseitig jede Kritik verbieten.","coreRule":"⚡ Ein anderer Missstand ist ein anderes Thema – er entlastet den ersten nicht.","beleg":"Werkstück D.1.5 (Kontext & Tiefe: Whataboutism; Das Anti-Denkmuster: Skript 2)","status":"entwurf","kurz":"Dass B mit der Polizeigewalt recht hat, ändert nichts an der Kritik an den Haftbedingungen. Der Konter lenkt vom ersten Punkt ab, statt ihn zu klären. Sinnvoll ist, beide Themen zu trennen und zur offenen Frage zurückzukehren.","prueffrage":"Über welchen Missstand in welchem Land hat A gesprochen, und worüber spricht B in seiner Antwort?","rueckmeldung":[{"option":0,"text":"B sagt zu den Haftbedingungen tatsächlich nichts. Schweigen ist aber kein Eingeständnis: Ob die Kritik stimmt, zeigt sich an den Haftbedingungen selbst, nicht daran, was B unerwähnt lässt."},{"option":2,"text":"Ein sachlicher Ton hilft jedem Gespräch. Im Konter von B geht es aber gar nicht um den Ton, sondern um ein anderes Thema. Die Entschuldigung ließe die Kritik unbeantwortet und klärt nichts."},{"option":3,"text":"Die Polizeigewalt ist real und verdient ein eigenes Gespräch. Die Kritik an den Haftbedingungen deshalb zurückzustellen, hieße aber, dass sich beide Seiten gegenseitig jede Kritik verbieten, bis alles in Ordnung ist."}],"familie":"du-auch-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Tu Quoque)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"cb911dc20baa4f16"}},{"id":"qx-d1-018","clusterId":"D","werkstueckRef":"D.1.5","stufe":3,"question":"Vier Personen reagieren auf Kritik oder auf Heuchelei. In welchem Satz wird der Heuchelei-Vorwurf berechtigt verwendet und nicht als Tu-quoque-Fehlschluss?","options":["„Die Wirtschaftszahlen von Politiker X können nicht stimmen, weil er Wasser predigt und Wein trinkt.“","„Dass Rauchen schädlich ist, kann nicht stimmen, denn die Ärztin, die uns das sagt, raucht ja selbst.“","„Meine Quellen sind genauso gut, denn die ‚Mainstream-Medien‘ haben schließlich auch schon gelogen.“","„Ich wähle Politiker X nicht, weil er Wasser predigt und Wein trinkt.“"],"correctIndex":3,"explanation":"Ein Heuchelei-Vorwurf ist berechtigt, wenn es um die Glaubwürdigkeit oder Eignung einer Person geht, etwa bei der Frage, ob man sie in ein Amt wählt. Zum Fehlschluss wird er, sobald er ein Tatsachenargument widerlegen soll. Ob Wirtschaftszahlen stimmen oder Rauchen schädlich ist, hängt an Daten und Belegen, nicht am Lebenswandel des Sprechers. Auch der Medien-Satz ist kein berechtigter Heuchelei-Vorwurf, sondern Whataboutism, eine Form des Tu quoque: Dass Medien Fehler machen, beweist nicht, dass andere Quellen stimmen. Ein Mörder, der „Morden ist falsch“ sagt, hat trotz seiner Heuchelei recht.","coreRule":"⚡ Heuchelei darf die Wahl einer Person beeinflussen, aber nie die Wahrheit ihrer Sachaussagen.","beleg":"Werkstück D.1.5 (Der Kipppunkt: legitim vs. Fehlschluss; Anwendung & Relevanz)","status":"entwurf","kurz":"Ob jemand für ein Amt glaubwürdig und geeignet ist, darf man am Verhalten messen; ob Zahlen oder Fakten stimmen, nicht. Der naheliegende Fehler ist, den Lebenswandel eines Sprechers gegen sein Argument zu wenden, obwohl Daten und Belege entscheiden.","prueffrage":"Was soll in jedem der vier Sätze am Ende entschieden oder bewiesen werden?","rueckmeldung":[{"option":0,"text":"Gegen Politiker X mag der Vorwurf berechtigt sein, wenn es um seine Glaubwürdigkeit geht. Hier soll er aber die Wirtschaftszahlen widerlegen, und ob Zahlen stimmen, zeigt sich an Daten und Belegen, nicht an seinem Lebenswandel."},{"option":1,"text":"Dass die Ärztin selbst raucht, mag widersprüchlich sein. Ob Rauchen schädlich ist, lässt sich aber nur an Studien und Daten prüfen, nicht am Verhalten der Sprecherin. Ihre Aussage bleibt davon unberührt."},{"option":2,"text":"Medien haben schon Fehler gemacht, das stimmt; der Satz ist aber kein Heuchelei-Vorwurf, sondern Whataboutism, eine Form des Tu quoque. Fehler der einen Seite sagen nichts darüber, ob die eigenen Quellen stimmen; auch die müssen sich prüfen lassen."}],"familie":"du-auch-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Tu Quoque)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"9a2c621a20c8fae1"}},{"id":"qx-d1-019","clusterId":"D","werkstueckRef":"D.1.5","stufe":4,"question":"Was folgt für die Frage, ob Homöopathie wirkt, selbst dann, wenn dieser Vorwurf stimmt?","scenario":"Du sagst, Homöopathie habe keine plausible Wirkung. Dein Gegenüber antwortet: „Und die Todesfälle und Nebenwirkungen der Schulmedizin? Die Pharmaindustrie ist viel schlimmer!“","options":["Es folgt nichts, weil der Gegenvorwurf nichts über die Wirksamkeit der Homöopathie aussagt.","Es folgt, dass beide Verfahren gleichwertig sind, weil jedes Verfahren seine Schattenseiten hat.","Es folgt, dass deine Kritik zurückgenommen werden muss, weil die Schulmedizin selbst Fehler macht.","Es folgt, dass die Homöopathie ein Stück weit bestätigt ist, weil sie im Vergleich besser dasteht."],"correctIndex":0,"explanation":"Der Konter wechselt von der Sachfrage („Wirkt Homöopathie?“) zu einem Gegenvorwurf gegen die Schulmedizin. Selbst wenn der Vorwurf gegen „Big Pharma“ zutrifft, beweist er nicht, dass Homöopathie wirkt. Ob sie wirkt, hängt allein an ihrer eigenen Plausibilität und Evidenz.","coreRule":"⚡ Die Fehler der anderen Seite sind kein Beleg für die eigene.","beleg":"Werkstück D.1.5 (Anwendung & Relevanz: Pseudomedizin & Esoterik)","status":"entwurf","kurz":"Der Gegenvorwurf betrifft die Schulmedizin, nicht die Homöopathie. Selbst wenn er stimmt, bleibt die Frage offen, ob Homöopathie wirkt; das hängt allein an ihrer eigenen Plausibilität und Evidenz.","prueffrage":"Welche Untersuchung bräuchte man, um zu klären, ob Homöopathie wirkt?","rueckmeldung":[{"option":1,"text":"Dass jedes Verfahren Schattenseiten hat, kann stimmen. Gleichwertig sind zwei Verfahren damit aber nicht: Schattenseiten sagen nichts darüber, ob und wie gut etwas wirkt."},{"option":2,"text":"Deine Kritik galt der Wirkung der Homöopathie, nicht der Fehlerlosigkeit der Schulmedizin. Fehler dort können real sein, ändern aber nichts an dem, was du über die Homöopathie gesagt hast."},{"option":3,"text":"Wer weniger Schäden anrichtet, steht beim Schaden besser da. Ob etwas wirkt, ist damit nicht gezeigt: Das hängt an der eigenen Evidenz, nicht am Vergleich mit einem anderen Verfahren."}],"familie":"du-auch-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Tu Quoque)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"adc5c3ee9e98d2ee"}},{"id":"qx-d1-020","clusterId":"D","werkstueckRef":"D.2.1","stufe":1,"question":"Was wäre der sinnvollste nächste Schritt, bevor du dich entscheidest?","scenario":"Bei einer Infoveranstaltung eines Tierheims erzählt eine Rednerin ohne eine einzige Zahl von „Rocky“, einem zitternden, abgemagerten Hund, der bei jeder Berührung zusammenzuckte. Ein kurzes Video zeigt, wie Rocky nach Wochen der Pflege wieder mit dem Schwanz wedelt. Eingeblendet wird: „Für nur 50 Cent am Tag kannst du die nächste Erfolgsgeschichte schreiben.“ Im Publikum werden Portemonnaies gezückt. Du überlegst, ob du spenden sollst.","options":["Du prüfst, ob die Geschichte von Rocky wirklich stimmt, etwa durch Nachfrage nach Datum, Ort und tierärztlichem Befund des Hundes.","Du fragst nach belegbaren Angaben dazu, wie viel Geld tatsächlich bei den Tieren ankommt und was die Programme bewirken.","Du schläfst eine Nacht darüber, damit sich die erste Rührung legt, und spendest nur, wenn dich die Geschichte danach noch berührt.","Du bittest um weitere Einzelschicksale wie Rocky, damit du dir ein vollständigeres Bild von der Arbeit des Tierheims machen kannst."],"correctIndex":1,"explanation":"Die Geschichte weckt Mitleid, und das ist verständlich. Sie beweist aber nichts über die Effizienz der Organisation: Sie zeigt nur, dass ein Tier gelitten hat und dass einem Einzelfall geholfen wurde, nicht ob das Tierheim insgesamt wirksam arbeitet. Die Emotion ist nicht das Problem; zum Fehlschluss wird sie, wenn sie Beweise und Logik ersetzt. Die Frage nach Mittelverwendung und Wirkung trennt die Gefühlslage vom eigentlichen Argument. Nötig sind faktische Belege, die unabhängig vom Gefühl gelten. Ob Rockys Geschichte stimmt, lässt sich prüfen, doch auch eine wahre Geschichte zeigt nur einen Einzelfall. Eine Nacht Abstand beruhigt das Gefühl, liefert aber keine Belege. Weitere Einzelschicksale bringen nur mehr vom Gleichen.","coreRule":"⚡ Eine bewegende Geschichte zeigt, dass jemand leidet – nicht, dass die Hilfe wirkt. Frage nach den Belegen, die auch ohne dein Gefühl gelten.","beleg":"Werkstück D.2.1 (Einstiegsszene „Die Rede im Tierheim“; Kontext & Tiefe: Appell an das Mitleid)","status":"entwurf","kurz":"Rockys Geschichte rührt, zeigt aber nur einen Einzelfall und nicht, ob das Tierheim insgesamt wirksam arbeitet. Gefühl ist kein Fehler, solange es Belege nicht ersetzt. Erst Angaben zu Mittelverwendung und Wirkung tragen die Entscheidung.","prueffrage":"Was hast du bei der Veranstaltung über das Tierheim erfahren, abgesehen davon, wie es Rocky ergangen ist?","rueckmeldung":[{"option":0,"text":"Nachzufragen, ob Rockys Geschichte stimmt, ist vernünftig und lässt sich auch prüfen. Selbst eine bestätigte Geschichte zeigt aber nur einen Einzelfall und sagt nichts darüber, wie wirksam das Tierheim insgesamt arbeitet."},{"option":2,"text":"Eine Nacht Abstand beruhigt die erste Rührung, und das ist durchaus nützlich. Belege bringt sie aber nicht: Am nächsten Morgen entscheidest du weiterhin allein nach dem Gefühl, nur gelassener, ohne etwas über Wirkung und Mittelverwendung zu wissen."},{"option":3,"text":"Mehr Geschichten fühlen sich wie mehr Information an, sind aber vom Gleichen mehr. Jeder weitere Einzelfall bestätigt höchstens, dass Tieren geholfen wurde, nicht wie viel Geld dort ankommt und was die Arbeit insgesamt bewirkt."}],"familie":"gefuehl-statt-argument","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Appeal to Emotions)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"5649b09f89bb8dd3"}},{"id":"qx-d1-021","clusterId":"D","werkstueckRef":"D.2.1","stufe":2,"question":"Woran erkennst du hier am ehesten einen manipulativen emotionalen Appell?","scenario":"Ein Werbespot zeigt nachts einen dunklen Hausflur, ein Geräusch, eine zitternde Familie, dazu düstere Musik – und dann das Angebot, zweimal hintereinander eingeblendet: „Mit der Alarmanlage XY schlafen Sie wieder ruhig.“","options":["Der Spot arbeitet mit Bildern und Musik statt mit Text, daher ist er ein Fehlschluss.","Die Lösung passt genau zur geweckten Emotion, und Prüfbares fehlt.","Der Spot löst Angst aus, daher ist die Bedrohung übertrieben dargestellt.","Der Spot wiederholt seine Botschaft mehrfach, daher ist er ein emotionaler Appell."],"correctIndex":1,"explanation":"Ein auffälliges Muster ist, dass erst eine Angst geweckt und im selben Moment die passende „Lösung“ angeboten wird. Bilder, Musik und Gefühle sind für sich kein Fehler: Ein Appell, der auf einer soliden faktischen Grundlage steht und Emotionen nutzt, um zum Handeln zu bewegen, ist legitim. Zum Trugschluss wird er erst, wenn die Emotion die einzige Grundlage ist und das Fehlen von Fakten verschleiert. Dass der Spot Angst auslöst, sagt nichts darüber, ob die Bedrohung übertrieben ist. Dass er seine Botschaft wiederholt, ist kein Kriterium für Manipulation. Entscheidend ist also, ob außer dem Gefühl etwas Überprüfbares geboten wird.","coreRule":"⚡ Achte darauf, wer dir Angst macht – und was er dir im selben Moment verkauft.","beleg":"Werkstück D.2.1 (Red Flags; Der Kipppunkt)","status":"entwurf","kurz":"Verdächtig wird der Spot, weil er erst Angst weckt und im selben Moment die passende Lösung anbietet, ohne dass etwas Prüfbares geboten wird. Emotion allein ist kein Fehler; sie wird erst zum Trugschluss, wenn sie die einzige Grundlage ist.","prueffrage":"Was bliebe von dem Spot übrig, wenn man Bilder und Musik weglässt und nur den eingeblendeten Satz liest?","rueckmeldung":[{"option":0,"text":"Bilder und Musik sind erst einmal nur Gestaltungsmittel, kein Fehler. Auch ein Spot ohne viel Text kann sachlich überzeugen, wenn er Prüfbares bietet. Entscheidend ist, was hinter den Bildern steht, nicht das Medium."},{"option":2,"text":"Dass Angst ausgelöst wird, stimmt, sagt aber nichts über die Größe der Bedrohung: Auch eine reale Gefahr macht Angst. Aufschlussreicher ist, ob der Spot außer dem Gefühl noch etwas Überprüfbares liefert."},{"option":3,"text":"Wiederholung allein macht einen Appell nicht manipulativ, denn auch sachliche Werbung wiederholt ihre Botschaft. Aussagekräftig ist, ob außer dem Gefühl etwas Prüfbares geboten wird."}],"familie":"gefuehl-statt-argument","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Appeal to Emotions)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"ab9519e414a528de"}},{"id":"qx-d1-022","clusterId":"D","werkstueckRef":"D.2.1","stufe":3,"question":"Wann würde dieser Appell tatsächlich zum Trugschluss?","scenario":"Eine Umweltorganisation zeigt Fotos verschmutzter Flüsse und nennt dazu gemessene Schadstoffwerte. Eine Freundin nennt das „Emotionsmache“ und meint, schon die Bilder machten den Appell unseriös.","options":["Sobald die Bilder Mitgefühl oder Empörung auslösen, weil dann das analytische Denken ausgeschaltet wird.","Sobald neben den Bildern auch Zahlen genannt werden, weil sich Gefühl und Zahl gegenseitig entwerten.","Sobald die Emotion die einzige Grundlage des Appells ist, weil sie dann das Fehlen von Fakten verschleiert.","Sobald die Organisation zusätzlich um Spenden bittet, weil ein Eigeninteresse jede Darstellung entwertet."],"correctIndex":2,"explanation":"Dass ein Argument Gefühle auslöst, macht es noch nicht fehlerhaft. Gefühle sind oft der Antrieb, sich überhaupt mit einem wichtigen Thema zu befassen. Ein Appell, der auf soliden Fakten steht und Emotionen nutzt, um zum Handeln zu bewegen, ist legitim. Zum Trugschluss wird er erst, wenn die Emotion die einzige Grundlage ist und das Fehlen von Fakten verschleiert. Hier tragen die gemessenen Schadstoffwerte das Argument; die Bilder machen es nur eindringlicher. Der Test: Würde die Behauptung auch dann noch gelten, wenn du die Gefühle beiseitelegst und nur die Belege betrachtest? Das Eigeninteresse einer Organisation oder die bloße Nennung von Zahlen widerlegt weder die Messwerte noch macht sie das Argument schwächer.","coreRule":"⚡ Gefühl darf der Antrieb sein – das Argument muss auch ohne das Gefühl tragen.","beleg":"Werkstück D.2.1 (Der Kipppunkt; Kontext & Tiefe)","status":"entwurf","kurz":"Der Appell kippt erst, wenn Emotion das Einzige ist, was ihn trägt, und Fakten fehlen. Gefühle allein entwerten ihn nicht: Hier stützen Messwerte die Aussage, die Bilder machen sie nur eindringlicher.","prueffrage":"Woher stammen die genannten Schadstoffwerte, und wer könnte sie nachmessen?","rueckmeldung":[{"option":0,"text":"Bilder können Mitgefühl und Empörung wecken, das stimmt. Daraus folgt aber nicht, dass das Denken abgeschaltet wird: Gefühle bringen Menschen oft erst dazu, sich mit einem Thema zu befassen. Entscheidend ist, ob Belege dahinterstehen."},{"option":1,"text":"Zahlen neben Bildern schwächen sich nicht gegenseitig. Gerade die Messwerte tragen hier das Argument, und die Bilder machen es anschaulicher. Fehlten die Zahlen, wäre der Appell angreifbarer, nicht umgekehrt."},{"option":3,"text":"Eine Spendenbitte zeigt ein Eigeninteresse, das du bei der Einordnung im Blick behalten kannst. Die Schadstoffwerte lassen sich aber unabhängig vom Absender nachprüfen, und ein Eigeninteresse macht sie nicht falsch."}],"familie":"gefuehl-statt-argument","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Appeal to Emotions)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"3dc71784503d21ad"}},{"id":"qx-d1-023","clusterId":"D","werkstueckRef":"D.2.2","stufe":1,"question":"Ein Kollege wendet ein: „Das ist doch völlig in Ordnung – gelogen hat der Manager nicht, es sind ja wirklich 50 Positionen.“ Was ist an dieser Verteidigung übersehen?","scenario":"Ein Manager kündigt eine „Freisetzung von Personalressourcen im Umfang von 50 Positionen“ an. Tatsächlich verlieren 50 Menschen ihren Job. In der Belegschaft klingt die Ankündigung deutlich weniger bedrohlich, als wenn der Manager gesagt hätte, 50 Mitarbeiter würden gekündigt.","options":["Dass eine Aussage ohne falsche Tatsache trotzdem lenken kann: Dieselbe Realität in milderen Worten verändert den Eindruck, ohne eine Lüge zu sein.","Dass eine Position nicht dasselbe sein muss wie ein Mensch: Die Zahl 50 könnte sich auf eine andere Größe beziehen als auf die Zahl der Betroffenen.","Dass die Zahl 50 wie ein Anker wirkt: Sie bestimmt vor allem, wie bedrohlich die Belegschaft den Einschnitt empfindet, gleich in welchen Worten er genannt wird.","Dass der Kollege sich auf die Stellung des Managers stützt: Eine Aussage wird nicht wahr, nur weil sie von einem Vorgesetzten kommt, und das gilt auch hier."],"correctIndex":0,"explanation":"Der Kollege prüft nur, ob die Zahl stimmt. Das tut sie: Die Ankündigung nennt 50 Positionen, und tatsächlich verlieren 50 Menschen ihren Job. Die milde Formulierung lügt also nicht, färbt die Realität aber durch die Wahl der Worte um. Gelenkt wird nicht über die Zahl, sondern über die Wortwahl. „Freisetzung von Personalressourcen“ ersetzt eine harte Aussage durch milde, vage Begriffe. Das ist ein Euphemismus, ein Weichzeichner. Die Verteidigung vermischt zwei Fragen: „Ist es wahr?“ und „Wie wird mein Urteil gelenkt?“. Ein Test: Ersetze die Begriffe durch die neutralsten, sachlichsten Wörter, die du findest. Übrig bleibt: 50 Menschen verlieren ihre Stelle. Dass dieser Satz anders wirkt als die Ankündigung, zeigt, wie viel die Wortwahl bewirkt hat. Dass mit den 50 Positionen tatsächlich 50 Menschen gemeint sind, steht hier fest, daran liegt es also nicht. Die Zahl ist in beiden Formulierungen gleich und kann den unterschiedlichen Eindruck deshalb nicht erklären. Und der Kollege beruft sich auf die Zahl, nicht auf die Stellung des Managers.","coreRule":"⚡ Ein Weichzeichner-Wort ändert den Eindruck, nicht die Tatsache.","beleg":"Werkstück D.2.2 (Einstiegsszene „Die Entscheidung des Managers“; „Kontext & Tiefe“, Punkt „Euphemismen (Die Weichzeichner)“; keine Fußnoten)","status":"entwurf","kurz":"Die Zahl stimmt, und trotzdem wirkt „Freisetzung von Personalressourcen“ anders als „50 Menschen verlieren ihre Stelle“. Wahr zu sein und den Eindruck zu lenken sind zwei Fragen; wer nur die erste prüft, übersieht, dass die Wortwahl die Realität umfärbt.","prueffrage":"Wie würde dieselbe Ankündigung klingen, wenn du nur die nüchternsten Wörter benutzt, die dir einfallen?","rueckmeldung":[{"option":1,"text":"Ob eine Position und ein Mensch dasselbe sind, lohnt bei Zahlen manchmal eine Nachfrage. Hier ist es aber geklärt: Tatsächlich verlieren 50 Menschen ihren Job. Die Zahl stimmt also, und der mildere Eindruck entsteht an anderer Stelle."},{"option":2,"text":"Die Zahl 50 steht in beiden Formulierungen, sie kann den unterschiedlichen Eindruck daher nicht erklären. Der Unterschied liegt in den Wörtern: „Freisetzung von Personalressourcen“ klingt viel milder als „Kündigung“, obwohl dieselbe Zahl genannt wird."},{"option":3,"text":"Dass eine Aussage nicht wahr wird, nur weil ein Vorgesetzter sie macht, stimmt grundsätzlich. Der Kollege beruft sich aber gar nicht auf die Stellung des Managers, sondern darauf, dass die Zahl stimmt. Der übersehene Punkt liegt woanders."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Walker, A. C. u. a. (2021): Controlling the narrative: Euphemistic language affects judgments of actions while avoiding perceptions of dishonesty. Cognition 211, 104633","oeffentlich":true,"doi":"10.1016/j.cognition.2021.104633","url":"https://pubmed.ncbi.nlm.nih.gov/33639377/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Loaded Language)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"f67ebbdd53db7fe5"}},{"id":"qx-d1-024","clusterId":"D","werkstueckRef":"D.2.2","stufe":2,"question":"Was folgt aus dieser Konstellation für die Beurteilung der drei Berichte?","scenario":"Drei Nachrichtenportale berichten über denselben Mann, der mit Waffengewalt gegen eine Regierung kämpft. Portal A nennt ihn „Freiheitskämpfer“, Portal B „Terrorist“, Portal C „Aufständischer“. Alle drei melden dieselben Fakten: Ort, Zeitpunkt, Anzahl der Angriffe.","options":["Die Berichte widersprechen sich in den Tatsachen, deshalb muss man sie gegeneinander abgleichen.","Wertende Wörter machen ein Portal insgesamt unzuverlässig, also sind auch die gemeldeten Tatsachen fraglich.","Weil alle drei Portale dieselben Tatsachen melden, wirken ihre Berichte auf die Leser auch gleich.","Alle drei Wörter können auf dieselbe Person passen, aber jedes legt schon ein bestimmtes Urteil nahe."],"correctIndex":3,"explanation":"Wörter haben eine Wörterbuch-Bedeutung (Denotation) und tragen zusätzlich Assoziationen (Konnotation). Alle drei Begriffe können auf denselben Mann passen, weil die Fakten übereinstimmen. Sie unterscheiden sich aber darin, ob sie ihn eher als Helden, als Schurken oder als neutralen Akteur erscheinen lassen. Das ist keine Lüge, aber eine Lenkung der Wahrnehmung: Das Urteil steckt schon im Wort. Wer die Berichte prüft, ersetzt die geladenen Wörter probeweise durch möglichst neutrale Beschreibungen („bewaffneter Kämpfer gegen die Regierung“) und fragt, was dann als nackte Tatsachenaussage übrig bleibt. Die Tatsachen widersprechen sich nicht, deshalb gibt es hier nichts abzugleichen. Dass die Portale dasselbe melden, heißt nicht, dass ihre Wörter gleich wirken. Und aus der Färbung der Wörter folgt nicht, dass die gemeldeten Fakten falsch sind; ihre Übereinstimmung spricht eher für sie.","coreRule":"⚡ Wörter beschreiben nicht nur, sie urteilen schon mit.","beleg":"Werkstück D.2.2 (Kontext & Tiefe: Geladene Sprache – denotativ/konnotativ; Das Anti-Denkmuster)","status":"entwurf","kurz":"Alle drei Wörter können auf denselben Mann passen, denn die Fakten stimmen überein. Doch jedes legt schon ein Urteil nahe: Held, Schurke oder neutraler Akteur. Gleiche Tatsachen heißen also nicht gleiche Wirkung der Wörter.","prueffrage":"Was bleibt von jedem Bericht übrig, wenn du die Bezeichnung für den Mann durch eine bloße Beschreibung ersetzt?","rueckmeldung":[{"option":0,"text":"Verschiedene Berichte abzugleichen ist oft sinnvoll. Hier melden aber alle drei Portale Ort, Zeitpunkt und Zahl der Angriffe übereinstimmend, die Tatsachen widersprechen sich also nicht. Unterschiedlich ist nur die Bezeichnung des Mannes."},{"option":1,"text":"Auffällige Wörter sind ein guter Anlass zur Aufmerksamkeit. Aber eine gefärbte Wortwahl ist keine Lüge, und aus ihr folgt nicht, dass die gemeldeten Fakten falsch sind. Dass alle drei Portale dieselben Fakten melden, spricht eher für diese."},{"option":2,"text":"Gleiche Fakten wirken nicht automatisch gleich: „Freiheitskämpfer“, „Terrorist“ und „Aufständischer“ lassen denselben Mann als Helden, Schurken oder neutralen Akteur erscheinen. Die Wirkung hängt an den Wörtern, nicht nur an den Tatsachen."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Loaded Language)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Walker, A. C. u. a. (2021): Controlling the narrative: Euphemistic language affects judgments of actions while avoiding perceptions of dishonesty. Cognition 211, 104633","oeffentlich":true,"doi":"10.1016/j.cognition.2021.104633","url":"https://pubmed.ncbi.nlm.nih.gov/33639377/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"2185305d2e4bf223"}},{"id":"qx-d1-025","clusterId":"D","werkstueckRef":"D.2.2","stufe":3,"question":"Was ist an dem Einwand des Kollegen fehlerhaft, und woran erkennst du, wann ein Euphemismus tatsächlich manipulativ wird?","scenario":"In einer Pressemitteilung steht: „Im Rahmen einer Neuausrichtung setzen wir 50 Personalressourcen frei.“ Gleichzeitig sagt jemand aus der Belegschaft einer Kollegin, die einen Angehörigen verloren hat: „Er ist von uns gegangen.“ Ein Kollege meint: „Beides ist derselbe Trick, denn beides schwächt ein hartes Wort ab. Wer so redet, manipuliert.“","options":["Der Einwand stimmt, weil jeder Euphemismus die Wirklichkeit verschleiert; manipulativ ist er also schon beim ersten beschönigenden Wort.","Der Einwand verwechselt Beschönigung mit Täuschung; manipulativ wird ein Euphemismus erst, wenn er eine falsche Tatsache behauptet.","Der Einwand stimmt, solange der Sprecher ein Eigeninteresse hat; ob die Absicht taktvoll ist, spielt für die Einordnung keine Rolle.","Der Einwand setzt Ungleiches gleich; Taktgefühl ist unproblematisch, manipulativ wird Wortwahl erst, wenn sie die Realität verzerrt."],"correctIndex":3,"explanation":"Ein weicheres Wort ist für sich genommen noch keine Manipulation. „Er ist von uns gegangen“ statt „Er ist tot“ drückt Mitgefühl aus, und alle Beteiligten wissen, was gemeint ist. Die Pressemitteilung dagegen kleidet den Verlust von 50 Arbeitsplätzen in Begriffe wie „Neuausrichtung“ und „Personalressourcen“, sodass die Betroffenen und ihr Schicksal kaum noch erkennbar sind. Das kippt, wenn Sprache systematisch dazu dient, die Realität so zu verzerren, dass eine nüchterne Bewertung kaum noch möglich ist. Die Pressemitteilung muss dafür nicht lügen: Sie beschreibt dieselbe Realität wie die harte Fassung, färbt sie aber um, sodass die eine Fassung harmlos wirkt und die andere brutal. Ein Prüfstein ist, die geladenen Wörter durch die neutralsten zu ersetzen und zu fragen, was als nackte Aussage übrig bleibt. Beim Trauerfall bleibt dieselbe Aussage und niemand wird getäuscht; bei der Pressemitteilung wird erst dadurch sichtbar, was geschieht.","coreRule":"⚡ Rücksicht in der Wortwahl ist Höflichkeit – erst die systematische Verzerrung macht daraus Manipulation.","beleg":"Werkstück D.2.2 (Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","kurz":"Zwei weiche Formulierungen sind nicht dasselbe: „von uns gegangen“ ist taktvoll, und alle wissen, was gemeint ist. Manipulativ wird Wortwahl erst, wenn sie die Realität so verzerrt, dass eine nüchterne Bewertung kaum noch möglich ist.","prueffrage":"Wüsste jemand, der nur einen der beiden Sätze hört, jeweils genau, was den Betroffenen geschehen ist?","rueckmeldung":[{"option":0,"text":"Dass Euphemismen die Wirklichkeit abmildern, stimmt. Daraus folgt aber keine Manipulation: Beim Trauerfall drückt das weichere Wort Mitgefühl aus, und niemand wird über das Geschehene getäuscht."},{"option":1,"text":"Beschönigung und Täuschung auseinanderzuhalten, ist ein guter Ansatz. Zu eng ist nur die Bedingung: Eine Pressemitteilung muss nichts Falsches behaupten, um zu manipulieren. Es genügt, dieselbe Realität so umzufärben, dass sie harmlos wirkt."},{"option":2,"text":"Ein Eigeninteresse kann ein Anlass sein, genauer hinzusehen. Es macht eine Wortwahl für sich aber nicht manipulativ, und die Absicht spielt durchaus eine Rolle: Wer mit „von uns gegangen“ Anteilnahme zeigt, verzerrt nichts."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Walker, A. C. u. a. (2021): Controlling the narrative: Euphemistic language affects judgments of actions while avoiding perceptions of dishonesty. Cognition 211, 104633","oeffentlich":true,"doi":"10.1016/j.cognition.2021.104633","url":"https://pubmed.ncbi.nlm.nih.gov/33639377/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Loaded Language)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"626e3063b100b9d7"}},{"id":"qx-d1-026","clusterId":"D","werkstueckRef":"D.2.2","stufe":4,"question":"Welche Prüfung hilft am besten, die Wirkung dieser Wortwahl zu durchschauen?","scenario":"Eine Broschüre schreibt: „Man leitet keine Gifte aus, man unterstützt den Körper bei seiner natürlichen Reinigung – ganzheitlich, sanft und harmonisierend.“","options":["Prüfen, ob der Satz in sich widerspruchsfrei ist und die einzelnen Teilaussagen logisch zusammenpassen, ohne einander auszuschließen.","Herausfinden, wer die Broschüre verfasst hat und was er sich davon verspricht, und die Aussagen anhand dieser Interessen einordnen.","Geladene Wörter und Beschönigungen probeweise durch neutrale, sachliche Begriffe ersetzen und fragen, welche Tatsachenbehauptung übrig bleibt.","Nachschlagen, was „ganzheitlich“, „sanft“ und „harmonisierend“ im Wörterbuch bedeuten, und diese Bedeutungen mit dem Satz abgleichen."],"correctIndex":2,"explanation":"Wörter wie „sanft“, „ganzheitlich“ oder „harmonisierend“ transportieren ein Urteil, ohne etwas zu belegen. Ersetzt du sie probeweise durch neutrale Begriffe, siehst du, was tatsächlich behauptet wird: dass der Körper Stoffe ausscheidet und dass die beworbene Methode dabei hilft. Genau diese Behauptung lässt sich dann prüfen: Welcher Stoff? Wie nachgewiesen? Mit welcher Wirkung? Auf Widersprüche zu prüfen ist sinnvoll, hier aber unergiebig, denn der Satz ist in sich stimmig und wirkt gerade durch seine Wortwahl. Die Absichten der Verfasser einzuordnen prüft die Aussage nicht selbst: Auch ein Mensch mit Eigeninteresse kann recht haben, und ein Mensch ohne kann sich irren. Im Wörterbuch nachzuschlagen hilft kaum, denn die Wörter sind nicht unklar, sondern gefärbt.","coreRule":"⚡ Streich die Gefühlswörter weg und schau, was als Behauptung übrig bleibt.","beleg":"Werkstück D.2.2 (Anwendung & Relevanz: In der Pseudomedizin; Das Anti-Denkmuster)","status":"entwurf","kurz":"Ersetzt du „sanft“ und „harmonisierend“ probeweise durch neutrale Wörter, bleibt die eigentliche Behauptung stehen: Der Körper scheidet Stoffe aus, und die Methode hilft dabei. Der Denkfehler wäre, den freundlichen Klang schon für einen Beleg zu halten.","prueffrage":"Welcher Stoff soll den Körper verlassen, und woran würdest du merken, dass die Methode dabei hilft?","rueckmeldung":[{"option":0,"text":"Auf Widersprüche zu achten ist grundsätzlich sinnvoll. Hier führt es aber nicht weit, denn der Satz ist in sich stimmig; seine Wirkung entsteht durch die gewählten Wörter, nicht durch einen logischen Bruch."},{"option":1,"text":"Wer etwas verkaufen will, hat womöglich ein Interesse, doch das sagt noch nichts darüber, ob die Aussage stimmt: Auch Interessierte können recht haben, Unbeteiligte sich irren. Die Behauptung selbst bleibt so ungeprüft."},{"option":3,"text":"Beim Nachschlagen findest du Bedeutungen, die du ohnehin kennst. Die Wörter sind ja nicht unklar, sondern gefärbt: Sie wirken freundlich und sagen kaum etwas darüber, was tatsächlich geschieht."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Loaded Language)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0d5b13e0cb0a1df5"}},{"id":"qx-d1-027","clusterId":"D","werkstueckRef":"D.2.3","stufe":1,"question":"Eine Leserin sagt: „Eine der beiden Zeitungen muss lügen, denn eine Steuererhöhung kann nicht zugleich Investition und Enteignung sein.“ Was ist an diesem Schluss fehlerhaft?","scenario":"Dieselbe Steuererhöhung wird in einer Zeitung als „Investition in die Gemeinschaft“, in einer anderen als „Enteignung durch den Staat“ beschrieben. Beide Zeitungen nennen dieselben Zahlen.","options":["Er übersieht, dass beide Begriffe denselben Sachverhalt in einen unterschiedlichen Deutungsrahmen setzen können, ohne dass eine Zeitung eine falsche Tatsache behauptet.","Er verallgemeinert aus zu wenigen Fällen: Vom Verhalten zweier Zeitungen schließt er auf die gesamte Presse, obwohl zwei Fälle dafür nicht reichen.","Er übersieht, dass die beiden Zeitungen von verschiedenen Zahlen ausgehen und deshalb gar nicht über denselben Sachverhalt berichten, sodass ihre Begriffe nicht vergleichbar sind.","Er übersieht, dass die Zeitungen unter „Steuererhöhung“ Verschiedenes verstehen und deshalb gar nicht über dieselbe Maßnahme schreiben, sodass ihre Begriffe nicht vergleichbar sind."],"correctIndex":0,"explanation":"Hier konkurrieren zwei Deutungsrahmen: der Gemeinschafts-Frame („Bürgerpflicht“, „Investition in die soziale Gemeinschaft“) und der Freiheits-Frame („Last“, „Enteignung durch den Staat“, Einschränkung der individuellen Freiheit). Je nachdem, welcher Frame dominiert, werden Steuererhöhungen als Investition oder als Diebstahl wahrgenommen. Der Unterschied liegt in Wortwahl und Blickwinkel, nicht in den Zahlen: Beide Zeitungen nennen dieselben Zahlen. Wer „Lüge“ ruft, verwechselt Rahmung mit Falschbehauptung. Beide Begriffe gehören zu je einem Deutungsrahmen. Besser ist die Frage: Welche anderen Frames gibt es, welche Aspekte hebt jeder hervor, welche lässt er außen vor, und zu welchen Lösungen würden wir kommen? Von der gesamten Presse ist in dem Schluss keine Rede, er betrifft nur diese beiden Zeitungen. Die Zeitungen gehen außerdem von denselben Zahlen aus und berichten über dieselbe Steuererhöhung. Der Streit liegt also nicht in den Fakten, sondern in der Rahmung.","coreRule":"⚡ Wer den Rahmen setzt, entscheidet mit, was dieselben Zahlen bedeuten.","quote":"Wer den Frame kontrolliert, kontrolliert die Debatte.","quoteLabel":"Zum Weiterdenken:","beleg":"Werkstück D.2.3 (Kontext & Tiefe: Beispiel Steuern)","status":"entwurf","kurz":"Zwei Begriffe können dieselbe Steuererhöhung aus verschiedenen Blickwinkeln beschreiben, ohne dass eine Zeitung eine falsche Tatsache nennt. Der Fehler liegt darin, Rahmung mit Falschbehauptung zu verwechseln.","prueffrage":"Was genau behaupten die beiden Zeitungen über die Steuererhöhung, wenn du Zahlen und Wertungen getrennt betrachtest?","rueckmeldung":[{"option":1,"text":"Zwei Fälle wären für eine Verallgemeinerung tatsächlich dünn. Die Leserin schließt aber gar nicht auf die gesamte Presse, sondern spricht nur über diese beiden Zeitungen. Der Fehler liegt woanders."},{"option":2,"text":"Das würde den Streit erklären, steht aber nicht im Szenario: Beide Zeitungen nennen dieselben Zahlen. Unterschiedlich ist nur die Beschreibung der Steuererhöhung, nicht die Faktenbasis."},{"option":3,"text":"Uneinheitlicher Wortgebrauch kann Vergleiche tatsächlich erschweren. Hier beschreiben aber beide Zeitungen dieselbe Steuererhöhung. Verschieden ist nur der Blickwinkel, nicht die Maßnahme."}],"familie":"rahmen-wechseln","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Thibodeau, P. H.; Boroditsky, L. (2011): Metaphors we think with: The role of metaphor in reasoning. PLoS ONE 6(2), e16782","oeffentlich":true,"doi":"10.1371/journal.pone.0016782","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy (Eintrag Loaded Language)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Lakoff, G. (2004): Don't Think of an Elephant! Know Your Values and Frame the Debate. White River Junction: Chelsea Green","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"7122b2f69f2a9fc5"}},{"id":"qx-d1-028","clusterId":"D","werkstueckRef":"D.2.3","stufe":2,"question":"Welche Erwartung ist am besten begründet, wenn die Klinik beide Entwürfe an Laien und an Ärzten testet?","scenario":"Eine Klinik will Patienten mit Lungenkrebs über zwei Behandlungswege aufklären: Operation oder Bestrahlung. Beide Entwürfe der Aufklärungsbroschüre geben dieselben Ergebnisse der Operation an. Entwurf 1 schreibt: „Die Ein-Monats-Überlebensrate liegt bei 90 Prozent.“ Entwurf 2 schreibt: „Im ersten Monat beträgt die Sterblichkeitsrate 10 Prozent.“ Ein Klinikleiter ist überzeugt: „Ärzte und Fachleute sind gegen solche Formulierungstricks gefeit. Nur medizinische Laien lassen sich davon beeinflussen.“","options":["Dass die Formulierung auch bei Ärzten die Entscheidung verschiebt, ist plausibel: Die Information ist gleich, aber der Rahmen aus Gewinn oder Verlust wirkt häufig unabhängig von Fachwissen.","Dass die Formulierung bei keiner Gruppe etwas verschiebt, ist plausibel: Wer dieselben Zahlen vor sich hat, rechnet sie um und entscheidet in der Regel gleich, wie sie dargestellt werden.","Dass sich nur Laien beeinflussen lassen, ist plausibel: Ärzte kennen die Behandlungsdaten genau und lassen sich von der Darstellung derselben Zahlen weitgehend nicht lenken.","Dass die Sterblichkeitsformulierung bei beiden Gruppen zu mehr Operationen führt, ist plausibel: Eine genannte Gefahr drängt meist zum raschen Handeln statt zum Abwarten."],"correctIndex":0,"explanation":"Der Klinikleiter behauptet etwas, das sich prüfen lässt: Schützt Fachwissen vor dem Rahmen? Genau das wurde 1982 untersucht (McNeil u. a., New England Journal of Medicine): 238 Patienten mit anderen chronischen Erkrankungen, 491 Studierende und 424 Ärzte sollten sich vorstellen, an Lungenkrebs erkrankt zu sein, und zwischen Operation und Bestrahlung wählen. In allen drei Gruppen war die Operation beliebter, wenn die Ergebnisse als Überlebenswahrscheinlichkeit statt als Sterblichkeit angegeben waren. Nach der Darstellung bei Kahneman (2012) wählten 84 Prozent der Ärzte die Operation, wenn von einer Ein-Monats-Überlebensrate von 90 Prozent die Rede war. Hieß es dagegen, im ersten Monat betrage die Sterblichkeitsrate 10 Prozent, zogen 50 Prozent die Bestrahlung vor. Gleiche Information führt also je nach Rahmen zu unterschiedlichen Entscheidungen, und Fachwissen schützt nicht davor. Dass man die Zahlen ineinander umrechnen kann, ändert daran nichts, denn gemessen wurde die Entscheidung, nicht das Rechnen. Dass nur Laien betroffen seien, widerspricht den Ergebnissen: Auch Ärzte entschieden je nach Formulierung anders. Und die Sterblichkeitsformulierung machte den Eingriff weniger attraktiv, nicht attraktiver.","coreRule":"⚡ Dieselbe Zahl als Gewinn oder als Verlust formuliert lenkt auch Fachleute: Wer eine Aussage prüft, sollte sie in beiden Rahmen lesen.","beleg":"Werkstück D.2.3 (Einstiegsszene); Fn. gl-d-mcneil (McNeil u. a. 1982, NEJM 306(21), S. 1259–1262; Kahneman 2012, Kap. 34)","status":"entwurf","kurz":"Ärzte entschieden bei „90 Prozent überleben“ ganz anders als bei „10 Prozent sterben“, obwohl es dieselben Zahlen sind. Fachwissen schützt also nicht vor dem Rahmen; der Fehler liegt darin, Immunität aus Kompetenz zu schließen, ohne sie zu prüfen.","prueffrage":"Worin unterscheiden sich die beiden Sätze, wenn die Zahlen dieselben sind, und was davon müsste ein Arzt anders lesen als ein Laie?","rueckmeldung":[{"option":1,"text":"Dass sich die Zahlen ineinander umrechnen lassen, stimmt. Gemessen wurde aber die Entscheidung, nicht das Rechnen, und die verschob sich je nach Darstellung deutlich, obwohl die Information dieselbe war."},{"option":2,"text":"Dass Ärzte die Behandlungsdaten besser kennen als Laien, stimmt. Dieses Wissen bewahrte sie aber nicht vor dem Rahmen: Auch bei ihnen kippte die Wahl je nach Formulierung deutlich."},{"option":3,"text":"Dass eine genannte Gefahr zum Handeln drängen kann, klingt nach einer üblichen Neigung. Hier lief es aber umgekehrt: Die Sterblichkeitsformulierung machte die Operation weniger attraktiv, nicht attraktiver."}],"familie":"rahmen-wechseln","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"McNeil, B. J.; Pauker, S. G.; Sox, H. C.; Tversky, A. (1982): On the elicitation of preferences for alternative therapies. NEJM 306(21), 1259–1262","oeffentlich":true,"doi":"10.1056/NEJM198205273062103","url":"https://pubmed.ncbi.nlm.nih.gov/7070445/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kahneman, D. (2012): Schnelles Denken, langsames Denken. München: Siedler, Kap. 34 „Frames und Wirklichkeit“, Abschnitt „Emotionales Framing“","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"2d836a1beb6ab786"}},{"id":"qx-d1-029","clusterId":"D","werkstueckRef":"D.2.3","stufe":3,"question":"Wie beurteilst du seine Aussage am besten?","scenario":"Ein Bekannter sagt: „Menschen denken in Frames, nicht in Fakten. Wer einmal in einem Rahmen steckt, den kannst du mit einer Richtigstellung nicht erreichen – das bringt nie etwas.“ Du hast den Verdacht, dass er die These übertreibt.","options":["Als zugespitzt: Rahmen lenken die Wahrnehmung stark, doch Richtigstellungen wirken meist, und nur selten verpuffen sie.","Als Zirkelschluss: Er setzt voraus, dass Fakten nicht ankommen, und folgert daraus, dass Fakten nicht ankommen.","Als Strohmann: Er widerlegt eine verzerrte Version der Gegenposition, statt sich mit der Gegenposition selbst zu befassen.","Als Autoritätsargument: Er stützt seine Behauptung auf das Ansehen einer Person statt auf Belege für den Effekt."],"correctIndex":0,"explanation":"Die Aussage macht aus einer Tendenz ein Gesetz. Dass wir Informationen durch Deutungsrahmen ordnen und passende Fakten leichter aufnehmen als unpassende, ist plausibel; daraus folgt aber nicht, dass Fakten nie ankommen. Richtigstellungen verringern eine Fehlvorstellung meist, wenn auch oft nicht vollständig und nicht auf Dauer; dass sie ganz verpuffen oder sich ins Gegenteil verkehren, ist die Ausnahme. Wer die Aussage prüft, fragt daher nicht „Gibt es Rahmeneffekte?“, sondern „Wie stark und wie oft?“. Absolute Wörter wie „nie“ oder „immer“ sind dabei ein Warnsignal. Ein Zirkelschluss liegt nicht vor, denn die Aussage dreht sich nicht im Kreis, sondern verallgemeinert zu stark. Ein Strohmann braucht eine Gegenposition, die verzerrt wiedergegeben wird, und davon ist hier nichts zu sehen. Und der Bekannte beruft sich auf keine Autorität, er stellt nur eine Behauptung auf.","coreRule":"⚡ Rahmen lenken die Wahrnehmung, aber Fakten verlieren nicht automatisch dagegen: Wer „nie“ sagt, überzieht eine Tendenz zum Gesetz.","beleg":"Werkstück D.2.3 (Kontext & Tiefe: Lakoffs These und Einschränkung; Der Kipppunkt)","status":"entwurf","kurz":"Rahmen lenken die Wahrnehmung tatsächlich, aber Richtigstellungen verringern Fehlvorstellungen meist und verpuffen nur selten. „Nie“ macht aus einer Tendenz ein Gesetz, und bei solchen absoluten Wörtern lohnt es sich, nach „wie stark und wie oft?“ zu fragen.","prueffrage":"Kennst du einen Fall, in dem jemand nach einer Richtigstellung seine Meinung tatsächlich geändert hat?","rueckmeldung":[{"option":1,"text":"Eine Behauptung zu stützen, indem man ihr Ergebnis schon voraussetzt, ist ein echter Fehler. Hier dreht sich die Aussage aber nicht im Kreis: Sie stützt sich auf die Rahmen-Idee und verallgemeinert sie dann zu stark, bis zu „nie“."},{"option":2,"text":"Ein Strohmann setzt voraus, dass jemand eine Gegenposition verzerrt wiedergibt. Im Satz kommt aber keine Gegenposition vor, der Bekannte stellt nur seine eigene These auf. Der Fehler liegt in ihrer Übertreibung, nicht in einer verdrehten Darstellung anderer."},{"option":3,"text":"Ein Autoritätsargument würde sich auf das Ansehen einer Person berufen. Der Bekannte nennt aber niemanden, er behauptet einfach etwas. Das Problem ist nicht, worauf er sich stützt, sondern dass die Behauptung mit „nie“ viel zu weit reicht."}],"familie":"rahmen-wechseln","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J.; Ecker, U. K. H. u. a. (2020): The Debunking Handbook 2020, Auszug Teil 3 „The elusive backfire effects“ (Skeptical Science); vollständig: DOI 10.17910/b7.1182","oeffentlich":true,"url":"https://skepticalscience.com/debunking-handbook-2020-elusive-backfire-effects.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Wood, T.; Porter, E. (2019): The Elusive Backfire Effect: Mass Attitudes' Steadfast Factual Adherence. Political Behavior 41(1), 135–163, DOI 10.1007/s11109-018-9443-y","oeffentlich":false},{"typ":"literatur","kurz":"Lakoff, G. (2004): Don't Think of an Elephant! Know Your Values and Frame the Debate. White River Junction: Chelsea Green","oeffentlich":false,"seite":"S. 17 (laut Belegregister)"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"a2e9f624b3c71129"}},{"id":"qx-d1-030","clusterId":"D","werkstueckRef":"D.2.3","stufe":4,"question":"Wie gehst du am klügsten mit dieser Rahmung um?","scenario":"In einer Debatte über Drogenpolitik wird das Thema durchgehend als „Krieg gegen Drogen“ geführt. Die Schlussfolgerung scheint schon in der Wortwahl mitzulaufen: Wer von Krieg spricht, denkt an Gegner, Härte und Sieg. Du willst den Rahmen nicht unbemerkt übernehmen.","options":["Zuerst die Faktenlage klären, denn erst wenn die Fakten feststehen, lohnt es sich, über Begriffe zu reden.","Die Interessen der Sprecher prüfen, denn wer eine Rahmung setzt, verfolgt meist ein Ziel, das man kennen sollte.","Den Rahmen benennen und alternative Rahmen durchspielen, denn so zeigt sich, was er sichtbar macht und was er ausblendet.","Die Begriffe zuerst sauber definieren, denn unklare Begriffe führen dazu, dass die Beteiligten aneinander vorbeireden."],"correctIndex":2,"explanation":"Ein Rahmen bestimmt, welche Aspekte eines Themas sichtbar werden und welche Lösungen naheliegen. Wer seinen Rahmen durchsetzt, hat oft schon gewonnen, bevor die erste Zahl genannt wird; wer ihn unbemerkt übernimmt, denkt innerhalb der Vorgaben anderer. Beim Rahmen „Krieg“ geht es dann um Gegner und Siege, nicht um Ursachen und Behandlung. Besser ist es, den Rahmen sichtbar zu machen und Alternativen zu prüfen: Was ändert sich, wenn das Problem als Gesundheitsproblem oder als Bildungsaufgabe betrachtet wird? Zu welchen anderen Lösungen käme man dann? Rahmungen sind dabei nicht per se manipulativ, denn ohne sie können wir die Welt gar nicht ordnen. Zum Problem werden sie, wenn wir den Rahmen nicht bemerken, in dem wir denken. Die Faktenlage zu klären ist richtig, ändert aber nichts an dem Rahmen, in dem die Fakten gelesen werden. Die Interessen der Sprecher zu kennen kann helfen, zeigt aber nicht, was das Bild vom „Krieg“ verdeckt. Und Begriffe zu definieren räumt Missverständnisse aus, die hier gar nicht vorliegen: Jeder versteht, was „Krieg“ meint.","coreRule":"⚡ Frag nicht nur, ob die Fakten stimmen, sondern in welchem Rahmen sie dir gezeigt werden.","beleg":"Werkstück D.2.3 (Das Anti-Denkmuster; Das Adaptive Talent)","status":"entwurf","quote":"Welche anderen, alternativen Frames gibt es?","quoteLabel":"Prüffrage","kurz":"Ein Rahmen legt fest, was sichtbar wird und welche Lösungen naheliegen. Wer ihn benennt und andere Rahmen durchspielt, sieht, was er ausblendet. Wer ihn unbemerkt übernimmt, denkt schon innerhalb fremder Vorgaben, bevor die erste Zahl fällt.","prueffrage":"Welche Maßnahmen gegen Drogenprobleme fallen dir ein, und welche davon passen zum Wort „Krieg“?","rueckmeldung":[{"option":0,"text":"Gesicherte Fakten sind wichtig, und es ist richtig, sie zu klären. Sie ändern aber nichts daran, dass der Rahmen schon bestimmt, welche Fakten zählen und wie man sie liest. Der Rahmen wirkt, bevor die erste Zahl genannt wird."},{"option":1,"text":"Das Ziel der Sprecher zu kennen kann durchaus helfen. Es sagt dir aber nur, wer den Rahmen setzt und warum, nicht, was das Bild vom „Krieg“ sichtbar macht und was es verdeckt. Auch ohne Hintergedanken würde dieser Rahmen dein Denken lenken."},{"option":3,"text":"Saubere Definitionen räumen Missverständnisse aus, die hier aber gar nicht vorliegen: Jeder versteht, was „Krieg“ meint. Das Problem ist nicht Unklarheit, sondern was die Metapher nahelegt, nämlich Gegner und Sieg statt Ursachen und Behandlung."}],"familie":"rahmen-wechseln","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Thibodeau, P. H.; Boroditsky, L. (2011): Metaphors we think with: The role of metaphor in reasoning. PLoS ONE 6(2), e16782","oeffentlich":true,"doi":"10.1371/journal.pone.0016782","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Lakoff, G.; Johnson, M. (1980): Metaphors We Live By. Chicago: University of Chicago Press; dt. Leben in Metaphern, 9. Aufl. Heidelberg: Carl-Auer 2018","oeffentlich":false,"seite":"Kap. 1, S. 11–13 (laut Landkarte-Fußnote gl-d-lakoffjohnson)"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"7c0f88b4b6caab5a"}},{"id":"qx-d1-031","clusterId":"D","werkstueckRef":"D.2.4","stufe":1,"question":"Was ist an diesem Argument der Kernfehler?","scenario":"Dein Nachbar warnt: „Erst Tempo 30 vor der Schule, dann in der ganzen Straße, dann ein Autoverbot in der Innenstadt – am Ende gehen wir alle zu Fuß!“ Belege für die einzelnen Schritte nennt er nicht.","options":["Er stellt dich vor nur zwei Möglichkeiten, als gäbe es keine dritte Wahl.","Er greift die Verkehrsplanerinnen und -planer persönlich an, statt auf die Sache einzugehen.","Er verwirft jede Warnung vor Folgen, weil Vorhersagen immer Spekulation sind.","Er stellt die Folgen als zwangsläufig dar, ohne sie zu belegen."],"correctIndex":3,"explanation":"Das ist ein Dammbruch-Fehlschluss (Slippery Slope): Eine kleine erste Maßnahme soll unweigerlich in einer Katastrophe enden. Der Fehler liegt in der behaupteten Zwangsläufigkeit. Es wird so getan, als gäbe es zwischen Tempo 30 vor der Schule und dem Autoverbot keine Haltepunkte, etwa Gesetze, Gerichte, öffentliche Proteste oder den gesunden Menschenverstand. Eine Warnung vor einer wahrscheinlichen, belegten Folge wäre dagegen kein Fehlschluss. Hier ist die Kette nur behauptet, kein einziger Übergang ist belegt. Ein persönlicher Angriff liegt nicht vor, und ein Entweder-oder wird nicht aufgemacht. Eine Warnung vor Folgen ist nicht per se ein Fehlschluss: Entscheidend ist, ob Wahrscheinlichkeit und Gewicht der befürchteten Folge begründet sind (vgl. Hahn/Oaksford 2006).","coreRule":"⚡ Prüfe jeden Pfeil der Kette einzeln, nicht nur das Schreckensbild am Ende.","beleg":"Werkstück D.2.4 (Kernidee; Kontext & Tiefe; Fußnote gl-d-hahn: Hahn/Oaksford 2006)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Der Nachbar behauptet eine Kette, in der jeder Schritt unweigerlich den nächsten auslöst, und belegt keinen einzigen Übergang. Dabei übersieht er mögliche Haltepunkte wie Gesetze, Gerichte oder Proteste.","prueffrage":"Was müsste zwischen Tempo 30 vor der Schule und einem Autoverbot in der Innenstadt alles geschehen und beschlossen werden?","rueckmeldung":[{"option":0,"text":"Ein Entweder-oder stellt zwei Möglichkeiten gegeneinander, der Nachbar reiht dagegen Schritt an Schritt. Was fehlt, ist keine dritte Wahl, sondern Belege dafür, dass jeder Schritt zwangsläufig den nächsten auslöst."},{"option":1,"text":"Das wäre ein Fehler, nur kommt er hier nicht vor: Der Nachbar sagt nichts über die Planenden als Personen, er warnt vor den Folgen der Maßnahmen. Der Schwachpunkt liegt in seiner Kette von Folgen."},{"option":2,"text":"Der Nachbar verwirft keine Warnungen, er spricht selbst eine aus. Warnungen vor Folgen sind auch nicht per se unzulässig; seine trägt nur nicht, weil er keinen Übergang der Kette begründet."}],"familie":"dammbruch-pruefen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Hahn, U.; Oaksford, M. (2006): A Normative Theory of Argument Strength. Informal Logic 26(1), 1–24","oeffentlich":true,"doi":"10.22329/il.v26i1.428","seite":"7","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: Fallacies (Abschnitt Slippery Slope). Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"f9c7da0dfcce4eca"}},{"id":"qx-d1-032","clusterId":"D","werkstueckRef":"D.2.4","stufe":2,"question":"Vier Personen warnen vor einer Entwicklung. Welche Warnung ist ein stichhaltiges Kausalargument und kein Dammbruch-Fehlschluss?","options":["„Wenn wir Tempo 30 in der Innenstadt einführen, folgt unweigerlich das Autoverbot, und am Ende bestimmt der Staat, wohin wir reisen dürfen.“","„Wenn du bei Glatteis 100 km/h fährst, ist die Wahrscheinlichkeit hoch, dass du die Kontrolle verlierst und einen schweren Unfall baust.“","„Wenn wir Schulnoten abschaffen, lässt der Ehrgeiz unweigerlich nach, dann sinkt das Niveau, und am Ende geht die ganze Wirtschaft zugrunde.“","„Wenn wir KI-Hilfe bei Hausaufgaben erlauben, denken Schüler bald nicht mehr selbst, und in einer Generation verlernt die Gesellschaft das Lesen.“"],"correctIndex":1,"explanation":"Die Glatteis-Warnung ist eine Wahrscheinlichkeitsaussage: Sie basiert auf Physik und Statistik, und die Kette ist probabilistisch und belegt. Die Warnung behauptet nur ein erhöhtes Risiko, keine Gewissheit. Die anderen drei Warnungen behaupten, dass die Kette unweigerlich bis zur Katastrophe läuft, und liefern für keinen einzelnen Übergang einen Beleg. Sie übergehen auch alle Bremsen, die in der Realität dazwischenstehen, etwa Gerichte, Verfassung, Gewaltenteilung, öffentlichen Protest oder die menschliche Vernunft. Dass über Tempo 30, Schulnoten oder KI-Hilfe tatsächlich gestritten wird und Bedenken dazu berechtigt sein können, macht diese Warnungen nicht stichhaltig: Es fehlt der Beleg, dass der erste Schritt zwangsläufig zum letzten führt. Entscheidend ist also nicht die Wenn-dann-Form, sondern ob eine Wahrscheinlichkeit belegt oder eine Zwangsläufigkeit nur behauptet wird.","coreRule":"⚡ Eine belegte Wahrscheinlichkeit ist eine Warnung – eine behauptete Zwangsläufigkeit ist Panikmache.","beleg":"Werkstück D.2.4 (Kontext & Tiefe: legitimes Kausalargument vs. Fehlschluss; Anwendung & Relevanz)","status":"entwurf","scenario":"In einer Diskussionsrunde fallen vier Wenn-dann-Warnungen. Du sollst entscheiden, welche davon ernst zu nehmen ist und welche nur Angst erzeugt.","kurz":"Die Glatteis-Warnung behauptet nur ein erhöhtes Risiko, das sich auf Physik und Statistik stützt. Der Fehler der anderen: Sie erklären die ganze Kette bis zur Katastrophe für zwangsläufig, ohne einen Übergang zu belegen.","prueffrage":"Welche der vier Folgen ließe sich an Beobachtungen oder Unfallzahlen überprüfen?","rueckmeldung":[{"option":0,"text":"Über Tempo 30 lässt sich berechtigt streiten. Die Warnung springt aber über mehrere Stufen bis zur staatlichen Reisekontrolle, nennt für keine einen Beleg und lässt Gerichte, Verfassung und Protest als Bremsen außer Acht."},{"option":2,"text":"Bedenken zur Notenabschaffung, etwa zur Motivation, können berechtigt sein. Aber „unweigerlich“ von sinkendem Ehrgeiz bis zum Wirtschaftsuntergang ist eine bloße Behauptung: Für keinen Übergang gibt es einen Beleg."},{"option":3,"text":"Dass KI-Hilfe das eigene Denken schwächen kann, ist ein berechtigtes Bedenken. Die Warnung erklärt aber den Weg bis zum verlernten Lesen für sicher, ohne zu belegen, dass er zwangsläufig so verläuft, und übergeht alles, was dazwischen bremsen kann."}],"familie":"dammbruch-pruefen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Hahn, U.; Oaksford, M. (2006): A Normative Theory of Argument Strength. Informal Logic 26(1), 1–24","oeffentlich":true,"doi":"10.22329/il.v26i1.428","seite":"7","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: Fallacies (Abschnitt Slippery Slope). Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"e288d4d5cfd99c57"}},{"id":"qx-d1-033","clusterId":"D","werkstueckRef":"D.2.4","stufe":3,"question":"Woran erkennst du, dass aus einer berechtigten Warnung ein Fehlschluss geworden ist?","scenario":"In einer Debatte über neue Technik sagt jemand zuerst: „Ich befürchte, das könnte das Risiko für Missbrauch erhöhen.“ Später heißt es: „Das wird unweigerlich zu totaler Überwachung führen!“","options":["Daran, dass die Warnung keine Zahlen zur Größe des Risikos nennt, denn Warnungen ohne Zahlen lassen sich schwerer auf ihre Stichhaltigkeit prüfen.","Daran, dass aus „könnte erhöhen“ ein „wird unweigerlich führen“ wird, denn damit ersetzt Zwangsläufigkeit die Wahrscheinlichkeit.","Daran, dass die Motive der Sprecherin unklar bleiben, denn Motive geben oft Hinweise darauf, wie ernst eine Warnung gemeint ist und wie viel sie wiegt.","Daran, dass die Sprecherin keine Gegenargumente nennt, denn eine Warnung ohne Abwägung dessen, was dagegen spricht, bleibt einseitig."],"correctIndex":1,"explanation":"Eine Warnung benennt ein Risiko: Etwas könnte wahrscheinlicher werden, und das lässt sich mit Belegen prüfen. Kippt sie in „wird unweigerlich“, wird eine Möglichkeit als Gewissheit ausgegeben, obwohl Bremsklötze wie Gesetze, Gerichte oder öffentliche Proteste die Kette unterbrechen können. Entscheidend ist der Übergang von Wahrscheinlichkeit zu Zwangsläufigkeit. Zahlen, Motive und Gegenargumente sind sinnvolle Prüfpunkte, aber die erste, berechtigte Warnung nannte weder Zahlen noch Motive noch Gegenargumente; diese Merkmale unterscheiden die beiden Aussagen also nicht.","coreRule":"⚡ „Könnte erhöhen“ ist eine Warnung, „wird unweigerlich“ ein Alarmruf ohne Beleg.","beleg":"Werkstück D.2.4 (Der Kipppunkt); Fn. gl-d-hahn (Hahn/Oaksford 2006, Informal Logic 26(1), S. 6–7)","status":"entwurf","kurz":"Berechtigt ist die Warnung, solange sie ein Risiko benennt, das sich prüfen lässt. Zum Fehlschluss wird sie, wenn aus „könnte erhöhen“ ein „wird unweigerlich“ wird und eine Möglichkeit als Gewissheit auftritt, obwohl Gesetze oder Proteste die Kette unterbrechen können.","prueffrage":"Was könnte zwischen der neuen Technik und totaler Überwachung noch dazwischenkommen, und lässt die zweite Aussage dafür Raum?","rueckmeldung":[{"option":0,"text":"Zahlen helfen tatsächlich beim Prüfen eines Risikos. Die erste, berechtigte Warnung nannte aber ebenfalls keine, deshalb unterscheidet dieses Merkmal die beiden Aussagen nicht."},{"option":2,"text":"Motive können Hinweise liefern, wie ernst eine Warnung gemeint ist. Über die Tragfähigkeit des Schlusses sagen sie aber nichts, und unklar waren sie schon bei der ersten, berechtigten Warnung."},{"option":3,"text":"Eine Abwägung mit Gegenargumenten macht eine Warnung ausgewogener. Auch die erste, berechtigte Warnung kam ohne sie aus, also liegt der Unterschied zur zweiten Aussage woanders."}],"familie":"dammbruch-pruefen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Hahn, U.; Oaksford, M. (2006): A Normative Theory of Argument Strength. Informal Logic 26(1), 1–24","oeffentlich":true,"doi":"10.22329/il.v26i1.428","seite":"7","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: Fallacies (Abschnitt Slippery Slope). Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Technik und KI","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"08146b23546a9bc7"}},{"id":"qx-d1-034","clusterId":"D","werkstueckRef":"D.2.4","stufe":4,"question":"Wie solltest du die Aussage der Kollegin beurteilen?","scenario":"Eine Kollegin meint: „Ein Dammbruch-Argument ist immer ein Fehlschluss. Die Form ‚A führt zu B, B zu C, C zu Z‘ taugt nichts.“ Du erinnerst dich an zwei Fälle: Wer bei Glatteis mit 100 km/h fährt, riskiert einen schweren Unfall. Wer behauptet, eine um eine Stunde verlängerte Sperrstunde führe „unweigerlich“ in die „24-Stunden-Anarchie“, nennt dagegen keinerlei Belege.","options":["Sie ist im Recht, weil die Wahrscheinlichkeit mit jedem Zwischenschritt sinkt und lange Ketten daher stets schwächer sind als kurze.","Sie ist zu pauschal, weil ein solches Argument umso stärker wird, je wahrscheinlicher und gewichtiger die befürchtete Folge ist.","Sie ist im Recht, weil die Beweislast beim Behauptenden liegt und Dammbruch-Argumente diese Last regelmäßig nicht erfüllen.","Sie ist im Recht, weil die bloße Möglichkeit einer Folge nichts über deren Wahrscheinlichkeit aussagt und deshalb kein Argument trägt."],"correctIndex":1,"explanation":"Die Form „A führt zu B, B zu C“ ist an sich weder gut noch schlecht, entscheidend ist der Inhalt. Die Warnung vor dem Glatteis-Unfall stützt sich auf Physik und Statistik: Die Folge ist wahrscheinlich und schwerwiegend, also trägt das Argument. Die Sperrstunden-Rede behauptet dagegen Zwangsläufigkeit ohne Beleg für einen einzigen Übergang und ignoriert alle Bremsen im System. Auch die Argumentationsforschung (Hahn und Oaksford) kommt zu diesem Ergebnis: Ein Dammbruch-Argument ist umso stärker, je realer die Chance der befürchteten Folge ist, und es lassen sich ausdrücklich „perfectly acceptable examples“ bilden. Klassische Fehlschlüsse sind Argumentformen, die je nach Inhalt unterschiedlich stark sein können. Der Fehler liegt in der behaupteten Zwangsläufigkeit: Eine Möglichkeit wird als Gewissheit dargestellt, und für die Übergänge fehlen die Belege. Er liegt nicht schon in der Wenn-dann-Form. Ebenso falsch wäre der Gegenschluss, jede Folgenwarnung sei gültig: Prüfe jeden Übergang einzeln. Dass die Wahrscheinlichkeit mit jedem Zwischenschritt sinkt, stimmt, macht kurze und belegte Ketten wie die Glatteis-Warnung aber nicht ungültig. Die Beweislast liegt zwar beim Behauptenden, im Glatteis-Fall wird sie aber erfüllt. Und die bloße Möglichkeit einer Folge sagt nichts über ihre Wahrscheinlichkeit, doch hier stützen Physik und Statistik genau diese Wahrscheinlichkeit.","coreRule":"⚡ Ob eine Folgenwarnung trägt, entscheidet ihr Inhalt (Wahrscheinlichkeit, Gewicht, Belege für jeden Übergang), nicht ihre Wenn-dann-Form.","beleg":"Werkstück D.2.4 (Kernidee; Red Flags); Fn. gl-d-hahn (Hahn/Oaksford 2006, Informal Logic 26(1), S. 6–7; 2007, Psychological Review 114(3), S. 704–732)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Ein Dammbruch-Argument ist weder immer gut noch immer schlecht: Es ist umso stärker, je wahrscheinlicher und gewichtiger die Folge ist. Der Fehler liegt in unbelegter Zwangsläufigkeit, nicht in der Wenn-dann-Form.","prueffrage":"Haben die Glatteis-Warnung und die Sperrstunden-Rede dieselbe Form, und sind sie gleich gut begründet?","rueckmeldung":[{"option":0,"text":"Dass die Wahrscheinlichkeit mit jedem unsicheren Schritt sinkt, stimmt. Daraus folgt aber nicht, dass lange Ketten stets taugen nichts: Eine kurze, gut belegte Kette wie die Glatteis-Warnung bleibt stark. Es kommt auf den Inhalt der Übergänge an."},{"option":2,"text":"Die Beweislast liegt tatsächlich beim Behauptenden, und die Sperrstunden-Rede erfüllt sie nicht. Beim Glatteis wird sie aber durch Physik und Statistik erfüllt. Dass die Last oft nicht erfüllt wird, macht die Form selbst nicht zum Fehlschluss."},{"option":3,"text":"Eine bloße Möglichkeit sagt tatsächlich nichts über ihre Wahrscheinlichkeit. Beim Glatteis geht es aber nicht um bloße Möglichkeit: Physik und Statistik stützen, dass die Folge wahrscheinlich ist. Deshalb kann das Argument sehr wohl tragen."}],"familie":"dammbruch-pruefen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Hahn, U.; Oaksford, M. (2006): A Normative Theory of Argument Strength. Informal Logic 26(1), 1–24","oeffentlich":true,"doi":"10.22329/il.v26i1.428","seite":"7","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Hahn, U.; Oaksford, M. (2007): The Rationality of Informal Argumentation: A Bayesian Approach to Reasoning Fallacies. Psychological Review 114(3), 704–732","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e4b05b57db3b8d06"}},{"id":"qx-d1-035","clusterId":"D","werkstueckRef":"D.2.5","stufe":2,"question":"Was spricht am stärksten gegen die Behauptung, solche Wendungen seien bloßer Sprachschmuck?","scenario":"Zwei Kollegen sprechen über eine Teamsitzung. Die eine sagt: „Er hat meine Position angegriffen, ich habe mich gut verteidigt, und am Ende habe ich die Debatte gewonnen.“ Der andere widerspricht: „Das ist doch nur Wortwahl. Sprache ist Schmuck, am Denken ändert sich nichts, wenn man ein anderes Wort benutzt.“","options":["Solche Wendungen sind so alltäglich, dass sie das Denken über Argumentieren unbemerkt als Kampf prägen, ohne als Bilder aufzufallen.","Solche Wendungen sind ein Stilmittel, das Redner bewusst wählen, um Aussagen anschaulicher und einprägsamer zu machen.","Solche Wendungen lassen sich in den meisten Fällen durch wörtliche Ausdrücke ersetzen, ohne dass sich an der Aussage etwas ändert.","Solche Wendungen haben ihren Ursprung in der Kriegssprache, wie die Herkunft von Wörtern wie „verteidigen“ und „angreifen“ zeigt."],"correctIndex":0,"explanation":"Wenn wir eine Position „verteidigen“, ein Argument „angreifen“ oder eine Debatte „gewinnen“, übertragen wir die Struktur eines Kampfes auf ein Gespräch. Solche Metaphern sind in der Alltagssprache so selbstverständlich, dass wir sie meist nicht mehr als Bilder bemerken und oft gar keine wörtliche Alternative zur Hand haben. Gerade deshalb sind sie kein austauschbarer Schmuck: Sie prägen im Hintergrund mit, was wir an einer Sache wahrnehmen (Gegner, Sieg, Niederlage). Dass Metaphern das Urteil lenken können, deutet ein Experiment von 2011 an: Derselbe Bericht über steigende Kriminalität führte zu deutlich mehr Zustimmung zu repressiven Maßnahmen, wenn Kriminalität als wildes Tier beschrieben wurde, als wenn sie als Virus beschrieben wurde (74 % gegenüber 56 %), obwohl die Fakten identisch waren und fast niemand das Bild als Ursache nannte. Dieses Experiment hatte allerdings keine Vergleichsgruppe ohne Metapher, und eine Wiederholung der Nachfolgestudie von 2013 fand 2014 keinen Metaphern-Effekt; die Größe und Robustheit des Effekts sind also umstritten. Die Wirkung setzt nicht voraus, dass die Metapher bewusst bemerkt wird: In der Nachfolgestudie von 2013 zeigte sich der Effekt sogar bei Personen, die sich an das Bild nicht mehr erinnerten. Dass Redner Bilder gezielt als Stilmittel nutzen, stimmt, betrifft aber nicht den Alltagsgebrauch, in dem niemand ein Bild wählt. Ließe sich eine Wendung ohne Verlust durch einen wörtlichen Ausdruck ersetzen, wäre sie tatsächlich Schmuck, doch gerade das gelingt hier oft nicht. Und dass die Wörter aus der Kriegssprache stammen, erklärt ihre Herkunft, sagt aber nichts darüber, ob sie heute das Denken prägen.","coreRule":"⚡ Wir benutzen die Bilder der Sprache, und sie benutzen unser Denken.","beleg":"Werkstück D.2.5 (Kontext & Tiefe); Fn. gl-d-lakoffjohnson (Lakoff/Johnson 1980; dt. Heidelberg: Carl-Auer, Kap. 1, S. 11–13, hier S. 12)","status":"entwurf","kurz":"Solche Wendungen sind so alltäglich, dass man sie kaum als Bilder bemerkt und oft keinen wörtlichen Ersatz hat. Deshalb sind sie kein austauschbarer Schmuck, sondern prägen mit, dass wir Argumentieren als Kampf mit Gegner und Sieg sehen.","prueffrage":"Welches andere Wort würdest du für „sich verteidigen“ in diesem Gespräch einsetzen, und fällt dir überhaupt eins ein?","rueckmeldung":[{"option":1,"text":"Bewusst gewählte Bilder gibt es tatsächlich, etwa in Reden. „Verteidigen“ oder „gewinnen“ wählt aber im Gespräch niemand als Bild aus; sie rutschen unbemerkt hinein, und genau dort liegt der Einwand gegen die Schmuck-Behauptung."},{"option":2,"text":"Ließe sich eine Wendung ohne Verlust ersetzen, wäre sie tatsächlich Schmuck. Bei solchen Alltagsmetaphern gelingt das aber oft nicht: Ein wörtlicher Ausdruck ist häufig gar nicht zur Hand, und der Wechsel würde die Aussage verschieben."},{"option":3,"text":"Die Herkunft der Wörter erklärt, woher sie kommen, nicht ob sie heute das Denken lenken. Der Schluss von der Entstehung auf die gegenwärtige Wirkung fehlt, und gerade diese Wirkung ist das Argument gegen den Schmuck-Einwand."}],"familie":"rahmen-wechseln","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Lakoff, G.; Johnson, M. (1980): Metaphors We Live By. Chicago: University of Chicago Press (dt. Leben in Metaphern, 9. Aufl. Heidelberg: Carl-Auer 2018), Kap. 1","oeffentlich":false},{"typ":"doi","kurz":"Thibodeau, P. H.; Boroditsky, L. (2011): Metaphors We Think With: The Role of Metaphor in Reasoning. PLoS ONE 6(2), e16782","oeffentlich":true,"doi":"10.1371/journal.pone.0016782","abruf":"2026-10-12"},{"typ":"doi","kurz":"Steen, G. J.; Reijnierse, W. G.; Burgers, C. (2014): When Do Natural Language Metaphors Influence Reasoning? A Follow-Up Study to Thibodeau and Boroditsky (2013). PLoS ONE 9(12), e113536","oeffentlich":true,"doi":"10.1371/journal.pone.0113536","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"822ea5264f30fcbc"}},{"id":"qx-d1-036","clusterId":"D","werkstueckRef":"D.2.5","stufe":4,"question":"Ein Kollege schickt dir eine Schlagzeile: „Studie belegt: Ein einziges Wort im ersten Satz verändert politische Urteile um fast 20 Prozentpunkte.“ Du recherchierst: Das Experiment hatte keine Vergleichsgruppe ohne Metapher. Eine unabhängige Wiederholung einer späteren Studie derselben Forschenden fand keinen Metaphern-Effekt; schon das Lesen über Kriminalität verschob die Antworten in Richtung Polizei und Strafe, gleich welches Bild der Text benutzte. Eine Auswertung von 91 Studien fand metaphorische Rahmen wirksam, aber nur schwach. Wie sicher darfst du die Schlagzeile nehmen?","options":["Die Behauptung ist als Richtwert brauchbar: Eine Auswertung von 91 Studien bestätigt den Effekt, also darf man auch mit einer Wirkung von fast 20 Prozentpunkten rechnen.","Die Behauptung lässt sich noch nicht beurteilen: Nach einer gescheiterten Wiederholung muss erst eine dritte Studie vorliegen, bevor sich überhaupt etwas über den Effekt sagen lässt.","Die Grundrichtung ist plausibel gestützt, die genannte Größe aber unsicher: Es fehlt eine Vergleichsgruppe ohne Metapher, und die Befunde streuen zwischen stark und kaum vorhanden.","Die Behauptung ist im Kern bestätigt: Auch die Wiederholung fand, dass der gelesene Text die Antworten verschiebt, also ändert schon ein einzelnes Wort das politische Urteil."],"correctIndex":2,"explanation":"Ein Befund wird nicht dadurch sicher, dass er eine eindrucksvolle Zahl liefert. Hier fehlt in der Ausgangsstudie die Vergleichsgruppe ohne Metapher: Man kann nicht erkennen, ob das Bild etwas bewirkt oder ob schon das Lesen über Kriminalität die Antworten in Richtung Polizei und Strafe verschiebt. Genau das zeigte eine unabhängige Wiederholung der Folgestudie (Steen, Reijnierse und Burgers 2014): kein Metaphern-Effekt; schon das Lesen über Kriminalität verschob die Antworten in Richtung Polizei und Strafe, gleich welches Bild der Text benutzte. Eine Auswertung von 91 Studien (Brugman u. a. 2019) fand metaphorische Rahmen dagegen wirksam, aber nur schwach. Die Auswertung stützt also eine Wirkung, aber nicht die Größe aus der Schlagzeile. Dass schon der Text die Antworten verschiebt, zeigt die Wirkung des Themas und nicht die eines einzelnen Wortes. Und auch ohne dritte Studie lässt sich ein abgestuftes Urteil fällen. Eine einzelne Replikation widerlegt nicht alles, und uneinheitliche Befunde machen nicht jede Aussage gleichwertig. Angemessen ist ein abgestuftes Urteil: Richtung plausibel, Größe und Robustheit offen.","coreRule":"⚡ Urteile über Studienbefunde abgestuft: Eine spektakuläre Zahl ohne Vergleichsgruppe und mit uneinheitlicher Replikation verdient „plausible Richtung, unsichere Größe“, weder blinden Glauben noch Totalverwurf.","beleg":"Werkstück D.2.5 (Hinweis zur Beleglage); Fn. gl-d-thibodeau (Thibodeau/Boroditsky 2011, 2013; Steen u. a. 2014, PLOS ONE 9(12), e113536; Brugman u. a. 2019, Language and Cognition 11(1), S. 41–65)","status":"entwurf","scenario":"","kurz":"Eine eindrucksvolle Zahl macht einen Befund nicht sicher: Ohne Vergleichsgruppe bleibt offen, ob das Bild wirkt oder schon das Thema. Die Befunde streuen von stark bis kaum vorhanden, also: Richtung plausibel, Größe unsicher.","prueffrage":"Was fanden die Wiederholung und die Auswertung der 91 Studien jeweils, gemessen an den fast 20 Prozentpunkten der Schlagzeile?","rueckmeldung":[{"option":0,"text":"Die Auswertung von 91 Studien findet tatsächlich eine Wirkung metaphorischer Rahmen, aber nur eine schwache. Sie stützt daher die Richtung, nicht die Größe von fast 20 Prozentpunkten aus der Schlagzeile."},{"option":1,"text":"Vorsicht nach einer gescheiterten Wiederholung ist richtig, und sie widerlegt nicht alles. Ein abgestuftes Urteil ist aber schon jetzt möglich: Die Richtung wirkt plausibel, die Größe ist offen. Dafür braucht es keine dritte Studie."},{"option":3,"text":"Dass schon der gelesene Text die Antworten verschiebt, stimmt, spricht aber gegen die Schlagzeile: Es zeigt die Wirkung des Themas, nicht die eines einzelnen Wortes. Die Wiederholung fand ja gerade keinen Metaphern-Effekt."}],"familie":"wiederholung-abwarten","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Steen, G. J.; Reijnierse, W. G.; Burgers, C. (2014): When Do Natural Language Metaphors Influence Reasoning? A Follow-Up Study to Thibodeau and Boroditsky (2013). PLoS ONE 9(12), e113536","oeffentlich":true,"doi":"10.1371/journal.pone.0113536","abruf":"2026-10-12"},{"typ":"doi","kurz":"Brugman, B. C.; Burgers, C.; Vis, B. (2019): Metaphorical framing in political discourse through words vs. concepts: a meta-analysis. Language and Cognition 11(1), 41–65 (Open Access)","oeffentlich":true,"doi":"10.1017/langcog.2019.5","abruf":"2026-10-12"},{"typ":"doi","kurz":"Thibodeau, P. H.; Boroditsky, L. (2011): Metaphors We Think With: The Role of Metaphor in Reasoning. PLoS ONE 6(2), e16782","oeffentlich":true,"doi":"10.1371/journal.pone.0016782","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"85804ac5035a1766"}},{"id":"qx-d1-037","clusterId":"D","werkstueckRef":"D.2.5","stufe":2,"question":"Welche Vermutung über die Wirkung des Kampfbildes ist am wahrscheinlichsten, und warum sollte man sie vor dem Start der Kampagne prüfen?","scenario":"Eine Gesundheitskampagne will Menschen zur Krebsvorsorge bewegen. Der Slogan lautet: „Gemeinsam den Krebs bekämpfen!“ Die Verantwortlichen sind überzeugt, das Kriegsbild wecke Dringlichkeit und motiviere zum Arztbesuch. Dafür gibt es bisher keine Belege; in vier Online-Studien mit Versuchspersonen ohne Krebserkrankung wurde allerdings untersucht, wie solche Kampfbilder wirken.","options":["Das Bild lässt die Krankheit übermächtig und die Behandlung schwierig erscheinen und kann Fatalismus verstärken, ohne dass die Bereitschaft zum Arztbesuch steigt.","Das Bild steigert die Wachsamkeit und weckt Dringlichkeit, sodass die Menschen eher zur Vorsorge gehen, wie die Verantwortlichen es erhoffen.","Das Bild hat keinerlei Wirkung auf die Lesenden, weder auf ihre Einschätzung der Behandlung noch auf ihr Verhalten.","Das Bild wirkt nur bei Menschen mit eigener Erkrankung, während es bei Gesunden folgenlos bleibt und deshalb keine Prüfung braucht."],"correctIndex":0,"explanation":"Die Hoffnung, ein Kampfbild wecke Dringlichkeit, ist eine plausible, aber ungeprüfte Annahme, und gut gemeinte Bilder haben oft Nebenwirkungen. In vier Online-Studien (Hauser und Schwarz 2020) ließ die Rede vom „Kampf“ gegen den Krebs die Behandlung schwieriger erscheinen und verstärkte den Fatalismus („gegen Krebs kann man ohnehin wenig tun“); die Bereitschaft, zum Arzt zu gehen, stieg nicht. Wer ein Bild für wirksam hält, sollte also messen, was es tatsächlich bewirkt, statt es vorauszusetzen. Vorbehalt: Untersucht wurden Personen ohne Krebserkrankung; Aussagen über Betroffene lassen sich daraus nicht ableiten.","coreRule":"⚡ Auch gut gemeinte Bilder wie der „Kampf“ haben Nebenwirkungen darauf, was Menschen für möglich halten. Ob ein Bild wirkt wie erhofft, muss man prüfen, nicht annehmen.","beleg":"Werkstück D.2.5 (Anwendung & Relevanz: Gesundheitspolitik); Fn. gl-d-kampfmetapher (Hauser/Schwarz 2020, Health Communication 35(13), S. 1698–1704)","status":"entwurf","kurz":"Ob ein Kampfbild wirkt wie erhofft, ist eine Annahme, die man messen muss. In vier Online-Studien ließ es die Behandlung schwieriger erscheinen und verstärkte den Fatalismus, ohne die Bereitschaft zum Arztbesuch zu erhöhen.","prueffrage":"Woran würdest du erkennen, dass ein Slogan Menschen tatsächlich zum Handeln bringt und nicht nur gut gemeint klingt?","rueckmeldung":[{"option":1,"text":"Dass ein Kampfbild Dringlichkeit weckt, klingt einleuchtend und ist genau die Hoffnung der Verantwortlichen. Belegt ist sie aber nicht, und in den Studien stieg die Bereitschaft zum Arztbesuch nicht."},{"option":2,"text":"Keine Wirkung wäre die harmloseste Annahme, doch in den Studien gab es eine: Die Behandlung erschien schwieriger, und der Fatalismus nahm zu. Nur die erhoffte Wirkung blieb aus, die Bereitschaft zum Arztbesuch stieg nicht."},{"option":3,"text":"Die Unterscheidung nach Erkrankung ist nicht abwegig, denn untersucht wurden nur Menschen ohne Krebs. Gerade bei ihnen zeigte das Bild aber Wirkungen: Die Behandlung erschien schwieriger, der Fatalismus nahm zu. Folgenlos ist es also nicht."}],"familie":"rahmen-wechseln","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Hauser, D. J.; Schwarz, N. (2020): The War on Prevention II: Battle Metaphors Undermine Cancer Treatment and Prevention and Do Not Increase Vigilance. Health Communication 35(13), 1698–1704 (Verlagsfassung, USC Dornsife)","oeffentlich":true,"doi":"10.1080/10410236.2019.1663465","url":"https://dornsife.usc.edu/norbert-schwarz/wp-content/uploads/sites/231/2023/12/20_HC_Hauser_Schwarz_War_on_cancer_II.pdf","seite":"1698","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"63cda4902b415b31"}},{"id":"qx-d1-038","clusterId":"D","werkstueckRef":"D.2.5","stufe":3,"question":"Was ist an der Forderung der Leserin am ehesten das Problem?","scenario":"Eine Zeitung berichtet über Migration. In jedem Artikel kommen „Flut“, „Welle“ und „Dämme“ vor, die genannten Zahlen sind korrekt. In Artikeln anderer Zeitungen über dieselben Zahlen ist von „Wanderungsbewegungen“, „Arbeitskräften“ oder einzelnen Lebensläufen die Rede. Eine Leserin sagt: „Naturbilder für Menschen sind grundsätzlich unzulässig, jede Zeitung müsste sie verbieten.“","options":["Sie verlangt ein Verbot von Bildern, obwohl jede Sprache über Migration irgendein Bild braucht; problematisch wird nur ein einziges Bild ohne Alternativen.","Sie übersieht, dass korrekte Zahlen im Text den Einfluss eines Bildes vollständig aufheben; ein Verbot ist daher überflüssig.","Sie übersieht, dass Leser ein lenkendes Bild sofort bemerken; deshalb braucht es keinen Schutz davor.","Sie verkennt, dass Naturbilder für Menschen nur irreführen, wenn die berichteten Zahlen falsch sind."],"correctIndex":0,"explanation":"Metaphern sind ein unvermeidbares Werkzeug des Denkens: Abstraktes lässt sich ohne Bilder kaum beschreiben, also kann es nicht darum gehen, Bilder zu verbieten. Problematisch wird ein Bild, wenn es zur einzigen Linse wird. Eine Naturkatastrophen-Metapher lässt Menschen unbemerkt als unpersönliche Naturgewalt erscheinen, gegen die man „Dämme“ baut, statt zu verhandeln, und Alternativen wie Wanderungsbewegung, Lebensläufe oder Arbeitsmarktfrage verschwinden aus dem Text. Dass Bilder auch bei korrekten Zahlen lenken, zeigte ein Experiment von Thibodeau und Boroditsky (2011): Bei identischer Kriminalstatistik unterschied sich die Zustimmung zu repressiven Maßnahmen je nach Tier- oder Virus-Bild um rund 18 Prozentpunkte, und fast niemand nannte die Metapher als Einflussfaktor. (Die genaue Größe und Robustheit des Effekts ist umstritten; seine Grundrichtung gilt aber als durch mehrere Studien gestützt.) Zu prüfen ist deshalb, ob es Alternativen zum Bild gibt und ob es offengelegt wird.","coreRule":"⚡ Nicht das Bild ist das Problem, sondern ein Bild ohne Alternative.","beleg":"Werkstück D.2.5 (Der Kipppunkt; Anwendung & Relevanz: Die eigene Argumentation)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"8c9cfd9df9d629a0","vermerk":"Prüfpult"},"kurz":"Ein Verbot geht am Problem vorbei, denn über Migration lässt sich kaum ohne irgendein Bild sprechen. Kritisch wird ein Bild erst, wenn es ohne Alternativen als einzige Linse steht und Menschen wie eine Naturgewalt erscheinen lässt.","prueffrage":"Welche anderen Wörter benutzen andere Zeitungen für dieselben Zahlen, und was zeigen sie anders?","rueckmeldung":[{"option":1,"text":"Zahlen im Text scheinen ein Gegengewicht zum Bild zu bilden. Im Experiment mit identischer Kriminalstatistik unterschied sich die Zustimmung trotzdem je nach Bild: Korrekte Zahlen heben den Einfluss eines Bildes nicht einfach auf."},{"option":2,"text":"Wörter wie „Flut“ fallen zwar auf, ihre lenkende Wirkung aber kaum: Im Experiment mit identischer Kriminalstatistik nannte fast niemand die Metapher als Einflussfaktor, obwohl die Zustimmung je nach Bild verschieden ausfiel."},{"option":3,"text":"Korrekte Zahlen schließen eine Täuschung durch Zahlen aus, aber keine Lenkung durch Bilder: In einem Experiment mit identischer Kriminalstatistik fiel die Zustimmung je nach Bild verschieden aus. Heikel wird ein Bild, wenn es die einzige Linse ist."}],"familie":"rahmen-wechseln","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Thibodeau, P. H.; Boroditsky, L. (2011): Metaphors We Think With: The Role of Metaphor in Reasoning. PLoS ONE 6(2), e16782","oeffentlich":true,"doi":"10.1371/journal.pone.0016782","abruf":"2026-10-12"},{"typ":"doi","kurz":"Brugman, B. C.; Burgers, C.; Vis, B. (2019): Metaphorical framing in political discourse through words vs. concepts: a meta-analysis. Language and Cognition 11(1), 41–65 (Open Access)","oeffentlich":true,"doi":"10.1017/langcog.2019.5","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Lakoff, G.; Johnson, M. (1980): Metaphors We Live By. Chicago: University of Chicago Press","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"8c9cfd9df9d629a0"}},{"id":"qx-d1-039","clusterId":"D","werkstueckRef":"D.3.1","stufe":1,"question":"Welche Schlussfolgerung ist hier am sinnvollsten?","scenario":"Eine Politikerin fordert in einer Rede, man müsse sich endlich um die „hart arbeitenden Familien in den Vorstädten“ und ihre „Werte“ kümmern. Ein Kommentator wirft ihr vor, sie sende damit verdeckt eine Botschaft an ihre Kernanhänger. Sie entgegnet empört: „Ich habe doch nur von Familien gesprochen! Wieso unterstellst du mir böse Absichten?“ Auffällig ist: Ihre Stammwählerschaft reagiert auf genau diese Formulierungen jedes Mal besonders begeistert, viele andere Zuhörer nehmen sie als Standardfloskel wahr.","options":["Im Zweifel gilt die harmloseste Lesart: Man sollte sich an den Wortlaut halten, denn nur er ist belegbar, und Vermutungen über Nebenbedeutungen bleiben Spekulation über das, was die Sprecherin im Stillen gemeint haben könnte.","Die Absicht ist Sache der Sprecherin: Man sollte ihre Erklärung als Maßstab nehmen, denn über das, was sie gemeint hat, kann letztlich nur sie selbst verlässlich Auskunft geben.","Die wörtliche Bedeutung allein entscheidet nichts: Man sollte prüfen, welche Assoziationen die Wörter bei der Zielgruppe wecken, und ob sich diese Deutung im Zusammenhang belegen lässt.","Der Inhalt zählt: Man sollte die Aussagen der Rede einem Faktencheck unterziehen, denn eine Botschaft ohne belegbare Tatsachen taugt nicht als Grundlage für politische Forderungen."],"correctIndex":2,"explanation":"Eine Botschaft kann auf zwei Kanälen laufen: für die Allgemeinheit harmlos, für Eingeweihte mit zusätzlicher Bedeutung. Das nennt man „Dog Whistling“ (Hundepfeife): Der hohe Ton einer Hundepfeife ist für Menschen unhörbar, für Hunde aber klar wahrnehmbar. Die Sprecherin gewinnt dadurch „plausible Abstreitbarkeit“ (plausible deniability): Sie kann auf den harmlosen Wortlaut verweisen. Die Wörter sind nur der Träger, die Assoziationen im Kopf des Empfängers sind die eigentliche Botschaft. Deshalb sagt der Wortlaut allein wenig. Auch die begeisterte Reaktion der Anhänger beweist die Absicht noch nicht, sie ist nur ein Hinweis. Ob wirklich ein Code vorliegt, zeigt sich an Anzeichen wie wiederholter Verwendung, starker Reaktion der Anhänger und dem Kontext bzw. der Geschichte der Phrase. Die harmloseste Lesart ist ein guter Ausgangspunkt, trägt aber nicht mehr, wenn Anzeichen wie die gleichbleibende Reaktion der Anhänger dagegensprechen. Die Erklärung der Sprecherin ist ein Datenpunkt, gerade bei plausibler Abstreitbarkeit aber kein Maßstab. Und ein Faktencheck prüft Tatsachenbehauptungen, die Rede enthält hier aber keine, sondern eine Forderung.","coreRule":"⚡ Die Botschaft steckt nicht allein im Wort, sondern in dem, was die Eingeweihten darin hören; prüfe darum immer, welchen Code eine Zielgruppe hören könnte und was sich dafür belegen lässt.","beleg":"Werkstück D.3.1 (Kernidee; Kontext & Tiefe)","status":"entwurf","kurz":"Der Wortlaut ist nur der Träger, die Botschaft entsteht im Kopf des Empfängers. Deshalb reicht „es steht ja nichts Böses da“ nicht: Man muss prüfen, was die Wörter bei der Zielgruppe auslösen und ob der Kontext diese Deutung stützt.","prueffrage":"Was weißt du über die Absicht der Politikerin sicher, und was schließt du nur aus Reaktionen oder Beteuerungen?","rueckmeldung":[{"option":0,"text":"Die harmloseste Lesart ist ein guter Ausgangspunkt, und der Wortlaut ist tatsächlich belegbar. Sie trägt aber nicht mehr, wenn Anzeichen dagegensprechen, etwa die gleichbleibend begeisterte Reaktion der Stammwähler. Solche Hinweise lassen sich prüfen, das ist keine bloße Spekulation."},{"option":1,"text":"Ihre Erklärung ist ein wichtiger Datenpunkt, schließlich kennt sie ihre Absichten am besten. Als Maßstab taugt sie hier aber nicht: Wer mit einer Doppelbotschaft arbeitet, kann sich gerade auf den harmlosen Wortlaut berufen, und entscheidend ist, was beim Publikum ankommt."},{"option":3,"text":"Ein Faktencheck ist dort richtig, wo Tatsachen behauptet werden. Die Rede enthält aber eine Forderung, an der es nichts zu überprüfen gibt. Die Frage nach einer zweiten Bedeutung der Wörter lässt sich auf diesem Weg nicht klären."}],"familie":"kodierte-botschaft","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Mendoza-Denton, N. (2023): Currents of Innuendo Converge on an American Path to Political Hate. Daedalus, Summer 2023 (American Academy of Arts & Sciences, Open Access)","oeffentlich":true,"url":"https://www.amacad.org/publication/daedalus/currents-innuendo-converge-american-path-political-hate","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Haney López, I. (2014): Dog Whistle Politics: How Coded Racial Appeals Have Reinvented Racism and Wrecked the Middle Class. New York: Oxford University Press","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"eb597241aecc4aca"}},{"id":"qx-d1-040","clusterId":"D","werkstueckRef":"D.3.1","stufe":2,"question":"Welche Schlussfolgerung ist aus dieser Reaktion gerechtfertigt?","scenario":"Ein Politiker spricht von „den hart arbeitenden Familien in den Vorstädten“ und „ihren Werten“. Eine Journalistin fragt, ob damit bestimmte Gruppen ausgegrenzt werden sollen. Er antwortet empört: „Ich habe doch nur von Familien gesprochen – warum legst du mir böse Dinge in den Mund?“","options":["Die Reaktion ändert nichts am Wortlaut, und der ist harmlos: „Familien“ und „Werte“ sind für sich genommen positiv besetzt, also liegt keine verdeckte Botschaft vor.","Die heftige Gegenwehr ist ein belastbares Indiz für eine verdeckte Botschaft, denn wer nichts zu verbergen hat, bleibt bei einer Nachfrage meist gelassen.","Die empörte Zurückweisung zeigt nur, dass die Phrase auch harmlos lesbar ist; ob ein Code vorliegt, lässt sie offen und muss am Zusammenhang geprüft werden.","Die Reaktion zeigt, dass die Nachfrage unfair war, denn schon die Frage nach einer verdeckten Botschaft ist eine Unterstellung, die der Redner nicht entkräften muss."],"correctIndex":2,"explanation":"Die Reaktion sagt über die Absicht des Redners wenig. Wer etwas Verdecktes meint, kann sich genau so äußern, denn eine harmlose Oberfläche erlaubt ihm, sich auf den Wortlaut zurückzuziehen und die Verantwortung für die Nebenbedeutung abzuweisen (plausible Abstreitbarkeit). Wer nichts Verdecktes meint, kann sich ebenso äußern, denn ein Unterstellungsvorwurf kann auch zu Unrecht erhoben werden. Ob die Empörung echt oder gespielt ist, lässt sich von außen kaum unterscheiden; sie ist deshalb weder Beweis noch Gegenbeweis. Ob ein Code vorliegt, zeigt erst die Prüfung am Zusammenhang, etwa an einer wiederholten Phrase mit auffällig starker Reaktion der Anhängerschaft, an einer nur Insidern verständlichen Bedeutung und an der Geschichte der Phrase. Dass die Wörter für sich positiv klingen, ist gerade die Eigenschaft solcher Codes und schließt eine Nebenbedeutung nicht aus. Und eine Nachfrage ist keine Unterstellung, die man nicht beantworten müsste: Man darf sie stellen, ohne das Ergebnis vorwegzunehmen.","coreRule":"⚡ Empörte Zurückweisung ist ein Warnzeichen, aber kein Beweis, weder für noch gegen eine verdeckte Botschaft.","beleg":"Werkstück D.3.1 (Einstiegsszene; Kontext & Tiefe: plausible Abstreitbarkeit; Red Flags)","status":"entwurf","kurz":"Die Empörung belegt weder eine verdeckte Botschaft noch widerlegt sie eine: Wer etwas Verdecktes meint, kann so reagieren, wer nichts meint, ebenso. Der Fehler wäre, aus der Heftigkeit der Reaktion auf die Absicht zu schließen; geklärt wird das erst am Zusammenhang.","prueffrage":"Was hat die Journalistin gefragt, und was davon beantwortet der Politiker in seiner Reaktion tatsächlich?","rueckmeldung":[{"option":0,"text":"Dass „Familien“ und „Werte“ positiv klingen, stimmt. Genau diese harmlose Oberfläche ist aber das, was einem Redner den Rückzug auf den Wortlaut erlaubt, sie schließt eine Nebenbedeutung also nicht aus."},{"option":1,"text":"Dass Unschuldige gelassen bleiben, klingt nach einer brauchbaren Faustregel. Eine Nachfrage kann aber auch zu Unrecht kränken, und echte von gespielter Empörung kann man von außen kaum unterscheiden. Als Indiz taugt sie deshalb nicht."},{"option":3,"text":"Ein Unterstellungsvorwurf kann tatsächlich zu Unrecht erhoben werden, und dann ist Ärger verständlich. Die Nachfrage selbst ist aber noch keine Unterstellung: Man darf sie stellen, ohne das Ergebnis vorwegzunehmen, und sie lässt sich beantworten."}],"familie":"kodierte-botschaft","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Mendoza-Denton, N. (2023): Currents of Innuendo Converge on an American Path to Political Hate. Daedalus, Summer 2023 (American Academy of Arts & Sciences, Open Access)","oeffentlich":true,"url":"https://www.amacad.org/publication/daedalus/currents-innuendo-converge-american-path-political-hate","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Albertson, B. L. (2015): Dog-Whistle Politics: Multivocal Communication and Religious Appeals. Political Behavior 37(1), 3–26","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"5337b94dcde7370c"}},{"id":"qx-d1-041","clusterId":"D","werkstueckRef":"D.3.1","stufe":3,"question":"Woran erkennst du am besten, dass im zweiten Forum aus harmloser Insider-Sprache eine problematische Taktik geworden ist?","scenario":"In einem Forum tauschen sich Angler in ihrem Fachjargon aus, den Außenstehende nicht verstehen. In einem anderen Forum benutzen Nutzer eine scheinbar harmlose Redewendung, die unter Eingeweihten als Erkennungszeichen für Verachtung gegenüber einer Minderheit gilt. Auf Kritik antworten sie empört: „Wir haben doch nur etwas Neutrales gesagt, ihr interpretiert da etwas hinein!“","options":["Die Redewendung bleibt Außenstehenden unverständlich, sodass die Gruppe sich vom Rest abgrenzt und bewusst unter sich bleibt.","Die Redewendung stärkt den Zusammenhalt der Gruppe, weil nur Eingeweihte sie verstehen, und schafft ein Gefühl der Zugehörigkeit.","Die Redewendung verbreitet Vorurteile gegenüber der Minderheit, und die Berufung auf ihre Harmlosigkeit verhindert eine ehrliche Debatte darüber.","Die Redewendung wird von den Nutzern regelmäßig und selbstverständlich verwendet, sodass sie zum festen Bestandteil des Umgangs wird."],"correctIndex":2,"explanation":"Auch der Angler-Jargon schließt Außenstehende aus und ist trotzdem unproblematisch: Insider-Sprache unter Freunden ist harmlos, denn eigene Sprache signalisiert Zugehörigkeit. Dass Außenstehende etwas nicht verstehen, ist also kein Beleg für Böswilligkeit. Dasselbe gilt für Gruppenzusammenhalt, der fast immer mit eigener Sprache einhergeht, und für die regelmäßige, selbstverständliche Verwendung, die jeder Fachjargon zeigt. Entscheidend ist, was der Code tut: Er wird zur toxischen Taktik, wenn er systematisch Vorurteile verbreitet und zugleich eine ehrliche Debatte nahezu unmöglich macht. Die gespielte Empörung auf Kritik schützt den Sprecher dabei vor Verantwortung. Dann ist aus Gruppenkultur eine Taktik der plausiblen Abstreitbarkeit geworden.","coreRule":"⚡ Ein Code unter Freunden ist Gruppenkultur; ein Code, der Vorurteile tarnt und Kritik mit „Ich habe doch nichts gesagt“ abwehrt, ist eine Taktik.","beleg":"Werkstück D.3.1 (Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","kurz":"Entscheidend ist nicht, dass Außenstehende etwas nicht verstehen, sondern was der Code tut: Er verbreitet Vorurteile und blockt zugleich jede ehrliche Debatte ab. Wer wie im Angler-Forum nur Zugehörigkeit stiftet, tut das nicht.","prueffrage":"Welche Merkmale teilt die Redewendung mit dem Angler-Jargon, und worin unterscheidet sie sich von ihm?","rueckmeldung":[{"option":0,"text":"Dass Außenstehende die Redewendung nicht verstehen, trifft genauso auf den Angler-Jargon zu. Abgrenzung nach außen gehört zu fast jeder Gruppensprache und zeigt noch keine böse Absicht."},{"option":1,"text":"Zusammenhalt und Zugehörigkeit sind tatsächlich Wirkungen von Insider-Sprache. Sie zeigen sich aber auch bei den Anglern, wo niemand etwas Problematisches sieht, und erklären daher den Unterschied zwischen beiden Foren nicht."},{"option":3,"text":"Regelmäßiger, selbstverständlicher Gebrauch gehört zu jedem Fachjargon, auch zu dem der Angler. Wie oft ein Ausdruck fällt, sagt noch nichts darüber, ob er Schaden anrichtet."}],"familie":"kodierte-botschaft","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Mendoza-Denton, N. (2023): Currents of Innuendo Converge on an American Path to Political Hate. Daedalus, Summer 2023 (American Academy of Arts & Sciences, Open Access)","oeffentlich":true,"url":"https://www.amacad.org/publication/daedalus/currents-innuendo-converge-american-path-political-hate","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Haney López, I. (2014): Dog Whistle Politics. New York: Oxford University Press","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e284f43c7435a561"}},{"id":"qx-d1-042","clusterId":"D","werkstueckRef":"D.3.1","stufe":4,"question":"Welcher Schluss ist aus dem Aufbau dieses Experiments am besten begründet?","scenario":"Ein Kandidat dreht ein Wahlvideo. Im letzten Satz will er eine Wendung aus einem Kirchenlied einbauen, die nur Menschen aus bestimmten Pfingstgemeinden als Anspielung erkennen. Ein Berater warnt: „Wenn wir das so sagen, verprellen wir alle anderen.“ Ein zweiter Berater hält dagegen: „Dann sagen wir es offen dazu: ‚As I sing in church‘.“ Ein Experiment mit US-Wählern hat genau diese beiden Fassungen verglichen.","options":["Die verdeckte Anspielung kann bei Eingeweihten gut ankommen, ohne Außenstehende messbar abzuschrecken; die offen religiöse Fassung ist dagegen riskanter.","Die verdeckte Anspielung schreckt Außenstehende messbar ab, während die offen religiöse Fassung bei allen Gruppen unauffällig bleibt.","Verdeckte Anspielungen bleiben ohne jede Wirkung, weil Menschen Botschaften, die sie nicht bewusst bemerken, auch nicht verarbeiten.","Eine verdeckte Anspielung kann nur wirken, wenn alle Zuschauer sie bewusst bemerken und als gezielte Botschaft erkennen."],"correctIndex":0,"explanation":"Entscheidend ist, wer die Anspielung überhaupt bemerkt. Wer die Wendung kennt, hört die Botschaft und bewertet den Kandidaten besser. Wer sie nicht kennt, hört einen gewöhnlichen Satz und hat keinen Anlass, sich zu stören. Der offene Zusatz dagegen ist für alle sofort als religiöse Aussage erkennbar und senkte in der gemischten Stichprobe Eindruck und Wahlabsicht. Genau so fiel das Ergebnis des Experiments (Albertson 2015) aus: Bei Pfingstlern, die das Lied kannten, verbesserte die Anspielung den Eindruck vom Kandidaten, ohne die Zuschauer einer gemischten Stichprobe messbar abzuschrecken; derselbe Satz mit offen religiösem Zusatz tat das sehr wohl. Die Gegenvarianten scheitern jeweils an einem Denkfehler: Die Anspielung musste von Außenstehenden nicht bemerkt werden, um bei Eingeweihten zu wirken, und die offene Fassung ist gerade nicht unauffällig. Vorbehalt: Es war ein Versuch mit religiöser Sprache in den USA; gemessen wurden Eindruck und Wahlabsicht, die Übertragung auf andere Anspielungen ist eine Annahme.","coreRule":"⚡ Wirkt eine Anspielung nur bei denen, die sie verstehen, stört sie die anderen nicht: Nicht bemerkt heißt nicht wirkungslos.","beleg":"Werkstück D.3.1 (Anwendung & Relevanz: In der Politik); Fn. gl-d-albertson. Albertson, B. L. (2015): Dog-Whistle Politics: Multivocal Communication and Religious Appeals. Political Behavior 37(1), 3–26, https://doi.org/10.1007/s11109-013-9265-x (Stichprobe 1: 402 Pfingstchristen, 84 % kannten die Wendung „wonder-working power“; Stichprobe 2: 783 Befragte, ohne die 24 %, die sie kannten; offener Zusatz „As I sing in church“; gelesen 12.10.2026 im Volltext, S. 9–14).","status":"entwurf","kurz":"Wer die Wendung kennt, hört die Botschaft und bewertet den Kandidaten besser; wer sie nicht kennt, hört einen gewöhnlichen Satz und stört sich nicht. Der offene Zusatz ist dagegen für alle erkennbar und senkte Eindruck und Wahlabsicht.","prueffrage":"Welche Zuschauer können in jeder der beiden Fassungen überhaupt merken, dass hier eine religiöse Aussage fällt?","rueckmeldung":[{"option":1,"text":"Dass ein verstecktes Signal mehr Ärger birgt als ein offenes, klingt plausibel. Gemessen wurde aber das Gegenteil: Der verdeckte Satz schreckte Außenstehende nicht messbar ab, der offen religiöse Zusatz senkte dagegen Eindruck und Wahlabsicht."},{"option":2,"text":"Richtig ist, dass Außenstehende die Anspielung nicht bemerken und deshalb nicht darauf reagieren. Daraus folgt aber keine Wirkungslosigkeit: Bei Pfingstlern, die das Lied kannten, verbesserte sie den Eindruck vom Kandidaten."},{"option":3,"text":"Eine Anspielung muss nicht alle erreichen, um zu wirken. Außenstehende überhörten sie und wurden nicht messbar abgeschreckt, und bei Eingeweihten, die das Lied kannten, kam sie gut an."}],"familie":"kodierte-botschaft","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Albertson, B. L. (2015): Dog-Whistle Politics: Multivocal Communication and Religious Appeals. Political Behavior 37(1), 3–26","oeffentlich":false},{"typ":"url","kurz":"Mendoza-Denton, N. (2023): Currents of Innuendo Converge on an American Path to Political Hate. Daedalus, Summer 2023 (American Academy of Arts & Sciences, Open Access)","oeffentlich":true,"url":"https://www.amacad.org/publication/daedalus/currents-innuendo-converge-american-path-political-hate","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e0a6493d1c09ad86"}},{"id":"qx-d1-043","clusterId":"D","werkstueckRef":"D.3.2","stufe":1,"question":"Wie reagierst du am klügsten auf diesen Gesprächsverlauf?","scenario":"In einer Diskussion über Staatsfinanzen sagt jemand: „Alle Steuern sind Diebstahl. Der Staat nimmt den Menschen mit Gewalt, was ihnen gehört.“ Du widersprichst und führst an, dass Straßen, Schulen und Gerichte aus Steuern bezahlt werden. Er antwortet: „Ich sage ja nur, dass die Regierung sparsam mit dem Geld der Bürger umgehen sollte. Willst du etwa Verschwendung verteidigen?“ Du merkst, dass du dem zweiten Satz kaum widersprechen kannst.","options":["Du stimmst zu, dass sparsames Haushalten wichtig ist, und fragst, ob er weiterhin hinter seiner ersten Aussage steht, dass alle Steuern Diebstahl sind.","Du legst mit Haushaltszahlen aus den letzten Jahren dar, dass der Staat nicht verschwenderisch wirtschaftet, und entkräftest so seinen Vorwurf der Verschwendung.","Du schlägst vor, über die gerechte Verteilung der Steuerlast zu sprechen, und lenkst das Gespräch auf einen Punkt, bei dem ihr konkrete Reformen vergleichen könnt.","Du suchst den gemeinsamen Nenner, dass sparsames Haushalten wichtig ist, und beendest das Gespräch dort, damit es nicht in einen Streit ausartet."],"correctIndex":0,"explanation":"Der Sprecher hat zwei Aussagen gemacht, die verschieden stark sind: eine radikale („Alle Steuern sind Diebstahl“), die schwer zu verteidigen ist, und eine harmlose („sparsam umgehen“), der fast jeder zustimmt. Unter Druck weicht er auf die harmlose aus und tut so, als habe er nie mehr gesagt. Wer nun nur die harmlose Aussage diskutiert, greift ins Leere, und der Sprecher kehrt später unbemerkt zur starken Behauptung zurück. Klug ist es, der unstrittigen Aussage ehrlich zuzustimmen und dann zur ursprünglichen, starken Behauptung zurückzuführen: „Stehst du noch zu deiner ersten Aussage?“ Dann muss er sich entscheiden. Entweder er verteidigt die radikale Aussage und trägt die argumentativen Kosten, oder er nimmt sie zurück. Beides ist ein ehrliches Ergebnis. Dieses Muster ist als Motte-and-Bailey-Täuschung bekannt (benannt nach der mittelalterlichen Burg: schwer zu verteidigende Vorburg, gut zu haltender Turmhügel; geprägt vom Philosophen Nicholas Shackel 2005). Ob die Regierung tatsächlich sparsam wirtschaftet, ist eine andere Frage und löst das Problem des Positionswechsels nicht. Auch ein Gespräch über die Verteilung der Steuerlast kann sinnvoll sein, lässt die erste Behauptung aber unberührt. Und im gemeinsamen Nenner zu enden wirkt versöhnlich, lässt aber offen, ob er zu seiner starken Aussage steht.","coreRule":"⚡ Stimm der harmlosen Aussage zu, aber bring das Gespräch zur ursprünglichen, starken Behauptung zurück und lass sie bestätigen oder zurücknehmen.","beleg":"Werkstück D.3.2 (Kontext & Tiefe); Fn. gl-d-shackel (Shackel 2005, Metaphilosophy 36(3), S. 295–320)","status":"entwurf","kurz":"Stimm dem Unstrittigen ehrlich zu und führe dann zur ersten Aussage zurück: Er muss sich nun entscheiden, ob er sie verteidigt oder zurücknimmt. Der Denkfehler wäre, nur über die harmlose Aussage zu streiten, denn die starke bliebe unberührt.","prueffrage":"Worüber habt ihr am Anfang gestritten, und worüber würdet ihr nach seiner Antwort streiten?","rueckmeldung":[{"option":1,"text":"Ob der Staat sparsam wirtschaftet, ist eine eigene Frage, die sich prüfen lässt. Behauptet hat er aber nur, die Regierung solle sparsam sein; dagegen anzuargumentieren trifft nichts, und die Aussage „Alle Steuern sind Diebstahl“ bleibt unberührt."},{"option":2,"text":"Über die Verteilung der Steuerlast zu reden kann durchaus lohnen und ist konkret. Die erste, radikale Behauptung bleibt dabei aber stehen, und er muss nie sagen, ob er sie noch vertritt."},{"option":3,"text":"Die Zustimmung zur Sparsamkeit ist ehrlich, und das Gespräch endet friedlich. Offen bleibt aber, ob er zu „Alle Steuern sind Diebstahl“ steht, und er kann später unbemerkt dorthin zurückkehren."}],"familie":"rueckzug-auf-harmloses","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shackel, N. (2014): Motte and Bailey Doctrines. Practical Ethics (Oxford Uehiro Centre), Blog, 05.09.2014","oeffentlich":true,"url":"https://blog.uehiro.ox.ac.uk/2014/09/motte-and-bailey-doctrines/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Shackel, N. (2005): The Vacuity of Postmodernist Methodology. Metaphilosophy 36(3), 295–320","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"adbb39c04dc77b75"}},{"id":"qx-d1-044","clusterId":"D","werkstueckRef":"D.3.2","stufe":2,"question":"Wie reagierst du am klügsten?","scenario":"Dein Gegenüber behauptet: „Homöopathie kann Grippe heilen.“ Du fragst nach Belegen. Er antwortet: „Ich sage ja nur, dass es den Placebo-Effekt wirklich gibt.“ Kurz darauf redet er wieder davon, dass man mit Homöopathie auf Medikamente gegen die Grippe verzichten könne.","options":["Der vernünftigen Aussage über den Placebo-Effekt zustimmen und ihn dann fragen, ob er weiterhin zu seiner ursprünglichen Heilungsbehauptung steht.","Ihn bitten, den Placebo-Effekt genauer zu erläutern, damit klar wird, wie weit seine harmlose Aussage über die Wirkung bei Grippe überhaupt reicht.","Ihn nach den Quellen für die Aussage über den Placebo-Effekt fragen, bevor du ihr zustimmst, denn Behauptungen sollte man vor der Zustimmung prüfen.","Ihn fragen, ob er selbst an homöopathischen Mitteln verdient, denn finanzielle Interessen können die Glaubwürdigkeit einer Behauptung beeinflussen."],"correctIndex":0,"explanation":"Hier wechselt jemand von einer starken, schwer zu belegenden Behauptung („heilt Grippe“) zu einer harmlosen, kaum bestreitbaren („den Placebo-Effekt gibt es wirklich“) und kehrt später zur starken zurück. Dieses Muster heißt Motte-and-Bailey, nach der mittelalterlichen Burg mit schwer haltbarem Vorhof (Bailey) und gut zu verteidigendem Turmhügel (Motte). Die harmlose Aussage zu bekämpfen führt ins Leere: Sie ist vernünftig und weithin akzeptiert, und gegen sie lässt sich kaum argumentieren. Der Ausweg ist, ihr zuzustimmen und die ursprüngliche Behauptung festzunageln („Pinning Down the Bailey“): „Stehst du noch zu deiner ersten Aussage?“ So muss er sich entscheiden. Entweder er verteidigt die starke Behauptung und muss Belege liefern, oder er gibt sie offen auf. Eine Meinung im Gespräch abzuschwächen ist ein Zeichen intellektueller Ehrlichkeit. Motte-and-Bailey ist das Gegenteil, weil der Rückzug nur ein Fluchtweg ist und die radikale Position danach unauffällig zurückkehrt. Den Placebo-Effekt genauer zu klären ist an sich sinnvoll, bleibt aber bei der harmlosen Aussage, statt die starke zu prüfen. Die Quelle dafür zu hinterfragen lohnt hier nicht, denn die Aussage ist weithin akzeptiert und war nie das Problem. Und die Frage nach finanziellen Interessen sagt nichts darüber, ob die Heilungsbehauptung stimmt.","coreRule":"⚡ Stimm der harmlosen Aussage zu und frag nach der starken.","beleg":"Werkstück D.3.2 (Das Anti-Denkmuster; Anwendung & Relevanz: Pseudomedizin & Esoterik)","status":"entwurf","kurz":"Der Placebo-Effekt ist weithin akzeptiert, ihn zu bestreiten führt ins Leere. Sinnvoll ist, ihm zuzustimmen und die ursprüngliche Behauptung festzunageln: Steht er noch dazu? So muss er sie verteidigen oder offen aufgeben.","prueffrage":"Wie verhält sich der Satz über den Placebo-Effekt zu dem, was er vorher und nachher über Homöopathie sagt?","rueckmeldung":[{"option":1,"text":"Den Placebo-Effekt genauer zu klären ist an sich sinnvoll. Es bleibt aber bei der harmlosen Aussage, die niemand ernsthaft bestreitet, während die starke Behauptung über die Grippe ungeprüft im Raum steht."},{"option":2,"text":"Belege einzufordern ist grundsätzlich gut. Hier setzt es aber an der falschen Stelle an: Die Aussage über den Placebo-Effekt ist weithin akzeptiert, ungeprüft ist die Heilungsbehauptung, und die ist es, bei der du nachhaken solltest."},{"option":3,"text":"Finanzielle Interessen können einen Grund zur Vorsicht geben. Ob Homöopathie Grippe heilt, entscheidet sich aber an den Belegen und nicht daran, wer verdient. Die Frage lenkt zudem von der Behauptung auf die Person."}],"familie":"rueckzug-auf-harmloses","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shackel, N. (2014): Motte and Bailey Doctrines. Practical Ethics (Oxford Uehiro Centre), Blog, 05.09.2014","oeffentlich":true,"url":"https://blog.uehiro.ox.ac.uk/2014/09/motte-and-bailey-doctrines/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"89214f280b87119e"}},{"id":"qx-d1-045","clusterId":"D","werkstueckRef":"D.3.2","stufe":3,"question":"Was ist an seinem Vorgehen fehlerhaft?","scenario":"Ein Kollege behauptet im Meeting: „Unser neues Lernprogramm macht jeden Mitarbeiter innerhalb einer Woche zum Top-Verkäufer.“ Du fragst nach Belegen. Er antwortet: „Ich habe nur gesagt, dass Weiterbildung grundsätzlich sinnvoll ist.“ Du stimmst zu. Kurz darauf wirbt er im Team wieder dafür, dass das Programm jeden zum Top-Verkäufer macht.","options":["Er legt seinen Kritikern eine Position in den Mund, die sie nie vertreten haben, und widerlegt dann diese verzerrte Darstellung.","Er hat sich nur zum Schein auf die harmlose Aussage zurückgezogen und die kühne Behauptung danach wieder vertreten, als wäre nichts gewesen.","Er stellt es so dar, als gäbe es nur die Wahl zwischen seinem Programm und gar keiner Weiterbildung, obwohl es viele andere Wege gibt.","Er begründet die Wirkung seines Programms mit nichts anderem als der Behauptung, dass es wirkt, und dreht sich damit im Kreis."],"correctIndex":1,"explanation":"Seine Behauptung hat sich nie geändert: Unter Kritik wich er auf eine leicht zu verteidigende Aussage aus, die kaum jemand bestreitet, und kehrte danach unauffällig zur kühnen Behauptung zurück. Dadurch wurde die starke Aussage nie wirklich geprüft. Eine Position abzuschwächen ist an sich ehrlich, wenn man die starke Aussage dauerhaft aufgibt. Hier wurde sie nur vorübergehend versteckt. Zum Prüfen hilft die Frage, ob er noch zur ursprünglichen Aussage steht: Wer sie bejaht, muss Belege liefern, wer sie verneint, hat sie aufgegeben. Dieses Muster heißt Motte-and-Bailey: Bei Kritik zieht man sich in die gut zu verteidigende „Motte“ zurück, die kühne „Bailey“ nimmt man später wieder ein. Ein Strohmann liegt nicht vor, denn er hat keinem Kritiker etwas unterstellt. Eine falsche Alternative ist ebenfalls nicht im Spiel, denn von anderen Weiterbildungen war nie die Rede. Und einen Zirkelschluss gibt es nicht, weil er für seine Behauptung gar keine Begründung angeführt hat.","coreRule":"⚡ Zurückrudern ist ehrlich, wenn die Position dauerhaft geräumt wird, nicht, wenn sie heimlich zurückkehrt.","beleg":"Werkstück D.3.2 (Kernidee; Der Kipppunkt; Red Flags)","status":"entwurf","kurz":"Er hat die kühne Behauptung nie aufgegeben, sondern nur vorübergehend hinter einer harmlosen Aussage versteckt und später wieder vertreten. Die starke Aussage blieb so ungeprüft. Der Fehler: Ein Rückzug auf Unstrittiges wird als Antwort auf die Kritik hingenommen.","prueffrage":"Was behauptet er im Meeting, was nach deiner Frage nach Belegen und was später im Team?","rueckmeldung":[{"option":0,"text":"Ein Strohmann verzerrt die Position der Gegenseite. Hier hat der Kollege aber niemandem etwas unterstellt. Du hast nur nach Belegen gefragt, und er wich selbst auf eine harmlose Aussage aus."},{"option":2,"text":"Eine falsche Alternative setzt ein Entweder-oder voraus. Von anderen Weiterbildungen oder von einer Wahl zwischen zwei Wegen war aber nie die Rede. Sein Fehler liegt woanders: Seine starke Aussage kam nach dem Rückzug einfach wieder."},{"option":3,"text":"Einen Zirkelschluss gäbe es nur, wenn er die Wirkung begründet hätte, etwa mit der Wirkung selbst. Er hat aber gar keine Begründung angeführt. Dass Belege fehlen, stimmt, doch das ist etwas anderes als ein Kreis."}],"familie":"rueckzug-auf-harmloses","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shackel, N. (2014): Motte and Bailey Doctrines. Practical Ethics (Oxford Uehiro Centre), Blog, 05.09.2014","oeffentlich":true,"url":"https://blog.uehiro.ox.ac.uk/2014/09/motte-and-bailey-doctrines/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"5e3191a3a767210a"}},{"id":"qx-d1-046","clusterId":"D","werkstueckRef":"D.3.2","stufe":4,"question":"Was ist an diesem Gesprächsverlauf aus Sicht der Prüfbarkeit das eigentliche Problem?","scenario":"In einer Diskussion behauptet jemand: „Unsere Methode heilt jede Krankheit, auch Krebs.“ Du fragst nach kontrollierten Studien. Er antwortet: „Ich meine ja nur, dass eine positive Einstellung wichtig für den Heilungsprozess ist.“ Du stimmst zu, und prompt sagt er wieder: „Siehst du, deshalb heilt unsere Methode eben jede Krankheit.“","options":["Die starke Behauptung wird bei Kritik so lange durch eine harmlose ersetzt, dass sie nie widerlegt werden kann, und kehrt danach unverändert zurück.","Die starke Behauptung ist so vage formuliert, dass sie nichts ausschließt und sich deshalb mit keiner denkbaren Beobachtung widerlegen lässt.","Die starke Behauptung stützt sich auf einzelne Erfolgsberichte statt auf Vergleichsdaten, sodass sich eine echte Wirkung nicht vom Zufall trennen lässt.","Deine Kritik wird verzerrt wiedergegeben, damit sie sich leichter abwehren lässt, und anschließend wird nur diese Verzerrung widerlegt."],"correctIndex":0,"explanation":"Eine Behauptung ist nur dann prüfbar, wenn man sagen kann, was sie ausschließt und woran sie scheitern würde. Hier geschieht das Gegenteil: Sobald es um Belege geht, verschwindet die kühne These und eine harmlose Aussage tritt an ihre Stelle, die kaum jemand bestreitet. Danach taucht die kühne These unverändert wieder auf, als wäre nichts gewesen. So wird sie nie wirklich getestet und kann nie scheitern, obwohl sie nie bestanden hat. Dass die harmlose Aussage stimmt, sagt nichts über die starke aus: Dass eine positive Einstellung beim Genesen helfen kann, belegt nicht, dass eine Methode Krebs heilt. Wirksam ist, die Debatte zur ursprünglichen Behauptung zurückzuführen: „Der gemäßigten Aussage stimme ich zu. Stehst du noch zu deiner ersten, viel stärkeren Behauptung? Denn sie war mein Kritikpunkt.“ Erst dann muss er sich entscheiden: belegen oder zurücknehmen. Vage ist die starke Behauptung nicht, denn „jede Krankheit, auch Krebs“ schließt viel aus und wäre durch einen einzigen Gegenfall zu Fall zu bringen. Erfolgsberichte ohne Vergleichsdaten wären ein berechtigter Einwand, nur hat er im Gespräch gar keine genannt. Und deine Kritik gibt er nicht verzerrt wieder, sondern weicht ihr aus.","coreRule":"⚡ Wer seine kühne These bei Kritik unsichtbar macht, entzieht sie der Widerlegung. Hake bei der ursprünglichen Behauptung nach, nicht beim Rückzugsort.","beleg":"Werkstück D.3.2 (Verbindungen: Falsifizierbarkeit; Anti-Denkmuster)","status":"entwurf","kurz":"Sobald es um Belege geht, tritt eine harmlose Aussage an die Stelle der kühnen, und danach kehrt die kühne unverändert zurück. So wird sie nie getestet. Dass die harmlose stimmt, sagt über die starke nichts.","prueffrage":"Woran müsste die Behauptung „heilt jede Krankheit“ scheitern können, und bekommt sie im Gespräch überhaupt eine Gelegenheit dazu?","rueckmeldung":[{"option":1,"text":"Vage ist die Behauptung nicht: „jede Krankheit, auch Krebs“ schließt viel aus, und ein einziger Gegenfall würde sie zu Fall bringen. Das Problem ist, dass sie bei Kritik durch eine harmlose Aussage ersetzt wird."},{"option":2,"text":"Fehlende Vergleichsdaten wären bei Erfolgsberichten ein berechtigter Einwand. Hier nennt der Sprecher aber gar keine Berichte, sondern wechselt zu einer anderen, harmlosen Aussage und kehrt dann zur starken zurück."},{"option":3,"text":"Eine verzerrte Wiedergabe deiner Kritik wäre ein Strohmann. Hier wird deine Frage aber richtig verstanden und nur umgangen: Statt Belege zu liefern, behauptet er etwas anderes, das kaum jemand bestreitet."}],"familie":"rueckzug-auf-harmloses","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shackel, N. (2014): Motte and Bailey Doctrines. Practical Ethics (Oxford Uehiro Centre), Blog, 05.09.2014","oeffentlich":true,"url":"https://blog.uehiro.ox.ac.uk/2014/09/motte-and-bailey-doctrines/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"e3cc4cad3b61cbe3"}}]`);export{t as n,n as t};